window.VOCES={"autores":[{"s":"seneca","n":"Séneca","r":"/recursos/voces-que-nos-habitan/autores/seneca/","y":"c. 4 a. C.–65","e":"fil","en":"Filosofía","p":"clasico","d":["Filosofía","Ética"]},{"s":"marco-aurelio","n":"Marco Aurelio","r":"/recursos/voces-que-nos-habitan/autores/marco-aurelio/","y":"121–180","e":"fil","en":"Filosofía","p":"clasico","d":["Filosofía","Ética"]},{"s":"sigmund-freud","n":"Sigmund Freud","r":"/recursos/voces-que-nos-habitan/autores/sigmund-freud/","y":"1856–1939","e":"pa","en":"Psicoanálisis","p":"moderno","d":["Psicoanálisis","Medicina","Psicología"]},{"s":"william-james","n":"William James","r":"/recursos/voces-que-nos-habitan/autores/william-james/","y":"1842–1910","e":"ini","en":"Los comienzos","p":"moderno","d":["Psicología","Filosofía","Medicina"]},{"s":"epicteto","n":"Epicteto","r":"/recursos/voces-que-nos-habitan/autores/epicteto/","y":"c. 50–135","e":"fil","en":"Filosofía","p":"clasico","d":["Filosofía","Ética"]},{"s":"friedrich-nietzsche","n":"Friedrich Nietzsche","r":"/recursos/voces-que-nos-habitan/autores/friedrich-nietzsche/","y":"1844–1900","e":"fil","en":"Filosofía","p":"moderno","d":["Filosofía","Filología"]},{"s":"buda","n":"Buda","r":"/recursos/voces-que-nos-habitan/autores/buda/","y":"s. VI–IV a. C.","e":"ori","en":"Tradiciones orientales","p":"clasico","d":["Espiritualidad","Filosofía"]},{"s":"lao-tse","n":"Lao-tse","r":"/recursos/voces-que-nos-habitan/autores/lao-tse/","y":"fechas inciertas","e":"ori","en":"Tradiciones orientales","p":"clasico","d":["Filosofía","Espiritualidad"]}],"temas":{"aceptacion":["Aceptación",true],"conciencia":["Conciencia",true],"autoconocimiento":["Autoconocimiento",true],"vinculos":["Vínculos",true],"identidad":["Identidad",true],"habitos":["Hábitos",true],"sufrimiento":["Sufrimiento",true],"cambio":["Cambio",true],"deseo":["Deseo",true],"resiliencia":["Resiliencia",true],"responsabilidad":["Responsabilidad",true],"muerte":["La muerte",true],"autenticidad":["Autenticidad",true],"sentido-de-vida":["Sentido de la vida",true],"presencia":["Presencia",true],"atencion":["Atención",true],"felicidad":["Felicidad",true],"conocimiento":["Conocimiento",true],"tiempo":["El tiempo",false],"ira":["Ira y agresión",true],"libertad":["Libertad",true],"verdad":["La verdad",true],"regulacion-emocional":["Regulación emocional",true],"inconsciente":["Lo inconsciente",false],"transformacion-personal":["Transformación personal",true],"amor":["Amor",true],"cuerpo":["El cuerpo",true],"educacion":["Aprender y enseñar",true],"miedo":["Miedo",true],"trascendencia":["Trascendencia",true],"compasion":["Compasión",true],"silencio":["Silencio",true],"naturaleza":["Naturaleza",true],"cultura":["Cultura",false],"alegria":["Alegría",true],"sociedad":["Sociedad",true],"comunicacion":["Comunicación",true],"existencia":["Existencia",true],"autoestima":["Autoestima",true],"desarrollo-humano":["Desarrollo humano",true],"poder":["Poder",true],"encuentro":["El encuentro",true],"trabajo":["Trabajo",true],"amistad":["Amistad",false],"angustia":["Angustia",false],"incertidumbre":["Incertidumbre",false],"voluntad":["Voluntad",false],"perdida":["Pérdida",false],"culpa":["Culpa",false],"infancia":["Infancia",false],"soledad":["Soledad",false],"esperanza":["Esperanza",false],"terapia":["Terapia",false],"duelo":["Duelo",false],"creatividad":["Creatividad",false],"suenos":["Sueños",false],"emociones":["Emociones",false],"humor":["Humor",false],"gratitud":["Gratitud",false],"conexion":["Conexión",false],"familia":["Familia",false],"memoria":["Memoria",false],"salud-mental":["Salud mental",false],"tristeza":["Tristeza",false],"tecnologia":["Tecnología",false],"repeticion":["Repetición",false],"trauma":["Trauma",false],"empatia":["Empatía",false]},"citas":[{"i":"seneca-001","a":"seneca","t":"Hacelo así, querido Lucilio: reclamate para vos mismo.","o":"Ita fac, mi Lucili: vindica te tibi","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 1","te":["autoconocimiento","libertad","tiempo"]},{"i":"seneca-002","a":"seneca","t":"Una gran parte de la vida se escapa haciendo mal, la mayor parte sin hacer nada, y la vida entera haciendo otra cosa.","o":"magna pars vitae elabitur male agentibus, maxima nihil agentibus, tota vita aliud agentibus","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 1","te":["tiempo","sentido-de-vida"]},{"i":"seneca-003","a":"seneca","t":"¿A quién podrás mostrarme que le dé algún valor al tiempo, que aprecie cada día, que entienda que muere cada día?","o":"Quem mihi dabis qui aliquod pretium tempori ponat, qui diem aestimet, qui intellegat se cotidie mori?","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 2","te":["tiempo","muerte"]},{"i":"seneca-004","a":"seneca","t":"Todo el tiempo que quedó atrás ya lo tiene la muerte.","o":"quidquid aetatis retro est mors tenet","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 2","te":["tiempo","muerte"]},{"i":"seneca-005","a":"seneca","t":"Mientras se la posterga, la vida pasa.","o":"Dum differtur vita transcurrit.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 3","te":["tiempo","cambio"]},{"i":"seneca-006","a":"seneca","t":"Todo, Lucilio, es ajeno: solo el tiempo es nuestro.","o":"Omnia, Lucili, aliena sunt, tempus tantum nostrum est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 3","te":["tiempo","libertad"]},{"i":"seneca-007","a":"seneca","t":"No está en ninguna parte quien está en todas.","o":"Nusquam est qui ubique est.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 2, 2","te":["presencia","atencion"]},{"i":"seneca-008","a":"seneca","t":"No es pobre quien tiene poco, sino quien desea más.","o":"non qui parum habet, sed qui plus cupit, pauper est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 2, 6","te":["deseo","felicidad"]},{"i":"seneca-009","a":"seneca","t":"Deliberá todo con tu amigo, pero antes deliberá sobre él.","o":"Tu vero omnia cum amico delibera, sed de ipso prius","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 3, 2","te":["amistad","vinculos"]},{"i":"seneca-010","a":"seneca","t":"Las dos cosas son un error: confiar en todos y no confiar en nadie.","o":"utrumque enim vitium est, et omnibus credere et nulli","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 3, 4","te":["vinculos","amistad"]},{"i":"seneca-011","a":"seneca","t":"Ningún bien se disfruta si no se lo comparte.","o":"nullius boni sine socio iucunda possessio est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 6, 4","te":["amistad","alegria","encuentro"]},{"i":"seneca-012","a":"seneca","t":"Más te servirán la voz viva y la convivencia que los discursos.","o":"Plus tamen tibi et viva vox et convictus quam oratio proderit","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 6, 5","te":["encuentro","educacion"]},{"i":"seneca-013","a":"seneca","t":"Retirate en vos mismo cuanto puedas; tratá con quienes te harán mejor y recibí a quienes vos podés hacer mejores.","o":"Recede in te ipse quantum potes; cum his versare qui te meliorem facturi sunt, illos admitte quos tu potes facere meliores.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 7, 8","te":["vinculos","autoconocimiento","transformacion-personal"]},{"i":"seneca-014","a":"seneca","t":"Esto es recíproco: los seres humanos, mientras enseñan, aprenden.","o":"Mutuo ista fiunt, et homines dum docent discunt.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 7, 8","te":["educacion","encuentro"]},{"i":"seneca-015","a":"seneca","t":"Para tener por quién morir, para tener a quién seguir al exilio. (Respuesta a “¿para qué buscás un amigo?”)","o":"Ut habeam pro quo mori possim, ut habeam quem in exsilium sequar","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 9, 10","te":["amistad","amor"]},{"i":"seneca-016","a":"seneca","t":"Son más, Lucilio, las cosas que nos asustan que las que nos aplastan, y sufrimos más a menudo por la opinión que por la realidad.","o":"Plura sunt, Lucili, quae nos terrent quam quae premunt, et saepius opinione quam re laboramus.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 13, 4","te":["miedo","sufrimiento","angustia"]},{"i":"seneca-017","a":"seneca","t":"Algunas cosas nos atormentan más de lo que deberían, otras antes de lo que deberían, y otras cuando no deberían atormentarnos en absoluto.","o":"Quaedam ergo nos magis torquent quam debent, quaedam ante torquent quam debent, quaedam torquent cum omnino non debeant","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 13, 5","te":["angustia","miedo","sufrimiento"]},{"i":"seneca-018","a":"seneca","t":"La filosofía no es un arte para el público ni hecho para la ostentación: no está en las palabras sino en los hechos.","o":"Non est philosophia populare artificium nec ostentationi paratum; non in verbis sed in rebus est.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 16, 3","te":["sentido-de-vida","autenticidad"]},{"i":"seneca-019","a":"seneca","t":"La naturaleza desea poco; la opinión, lo inmenso.","o":"Exiguum natura desiderat, opinio immensum.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 16, 8","te":["deseo","felicidad"]},{"i":"seneca-020","a":"seneca","t":"¿Qué es la sabiduría? Querer siempre lo mismo y rechazar siempre lo mismo.","o":"quid est sapientia? semper idem velle atque idem nolle.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 20, 5","te":["identidad","autenticidad"]},{"i":"seneca-021","a":"seneca","t":"Antes que nada, querido Lucilio, hacé esto: aprendé a alegrarte.","o":"Hoc ante omnia fac, mi Lucili: disce gaudere.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 23, 3","te":["alegria","felicidad"]},{"i":"seneca-022","a":"seneca","t":"La verdadera alegría es una cosa seria.","o":"verum gaudium res severa est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 23, 4","te":["alegria","felicidad"]},{"i":"seneca-023","a":"seneca","t":"Quien dice esto [“meditá sobre la muerte”] nos manda meditar sobre la libertad. Quien aprendió a morir desaprendió a servir.","o":"qui hoc dicit meditari libertatem iubet. Qui mori didicit servire dedidicit","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 26, 10","te":["muerte","libertad"]},{"i":"seneca-024","a":"seneca","t":"Una mente buena no se presta ni se compra.","o":"Bona mens nec commodatur nec emitur","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 27, 8","te":["autoconocimiento","transformacion-personal"]},{"i":"seneca-025","a":"seneca","t":"Morimos cada día: cada día se nos quita una parte de la vida, y aun cuando crecemos, la vida decrece.","o":"Cotidie morimur; cotidie enim demitur aliqua pars vitae, et tunc quoque cum crescimus vita decrescit.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 24, 20","te":["muerte","tiempo","cambio"]},{"i":"seneca-026","a":"seneca","t":"Tenés que cambiar de ánimo, no de cielo.","o":"Animum debes mutare, non caelum.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 28, 1","te":["transformacion-personal","cambio"]},{"i":"seneca-027","a":"seneca","t":"¿Te preguntás por qué esa huida no te ayuda? Huís con vos mismo.","o":"Quaeris quare te fuga ista non adiuvet? tecum fugis.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 28, 2","te":["autoconocimiento","cambio","sufrimiento"]},{"i":"seneca-028","a":"seneca","t":"Dios está cerca de vos, está con vos, está adentro.","o":"prope est a te deus, tecum est, intus est.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 41, 1","te":["trascendencia","conciencia"]},{"i":"seneca-029","a":"seneca","t":"Dentro de nosotros habita un espíritu sagrado, observador y guardián de nuestros males y nuestros bienes.","o":"sacer intra nos spiritus sedet, malorum bonorumque nostrorum observator et custos","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 41, 2","te":["conciencia","trascendencia"]},{"i":"seneca-030","a":"seneca","t":"“Son esclavos”. No: son seres humanos.","o":"'Servi sunt.' Immo homines.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 47, 1","te":["sociedad","encuentro"]},{"i":"seneca-031","a":"seneca","t":"Si querés vivir para vos, tenés que vivir para otro.","o":"alteri vivas oportet, si vis tibi vivere.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 48, 2","te":["vinculos","sentido-de-vida","encuentro"]},{"i":"seneca-032","a":"seneca","t":"Nuestro mal no viene de afuera: está dentro de nosotros, asentado en las mismas entrañas.","o":"non est extrinsecus malum nostrum: intra nos est, in visceribus ipsis sedet","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 50, 4","te":["sufrimiento","autoconocimiento"]},{"i":"seneca-033","a":"seneca","t":"Nadie es lo bastante fuerte para salir a flote solo: hace falta que alguien le tienda la mano, que alguien lo saque.","o":"Nemo per se satis valet ut emergat; oportet manum aliquis porrigat, aliquis educat.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 52, 2","te":["vinculos","terapia","resiliencia"]},{"i":"seneca-034","a":"seneca","t":"Que los ojos no estén secos al perder a un amigo, ni desborden: hay que llorar, no lamentarse a gritos.","o":"Nec sicci sint oculi amisso amico nec fluant; lacrimandum est, non plorandum.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 63, 1","te":["duelo","tristeza","perdida"]},{"i":"seneca-035","a":"seneca","t":"Aquel a quien creés perdido, solo se adelantó.","o":"quem putas perisse praemissus est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 7","te":["duelo","muerte","perdida"]},{"i":"seneca-036","a":"seneca","t":"Nadie muere sino en su día.","o":"nemo nisi suo die moritur","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 69, 6","te":["muerte"]},{"i":"seneca-037","a":"seneca","t":"Lo bueno no es vivir, sino vivir bien.","o":"non enim vivere bonum est, sed bene vivere.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 70, 4","te":["sentido-de-vida"]},{"i":"seneca-038","a":"seneca","t":"Para quien no sabe a qué puerto se dirige, ningún viento es favorable.","o":"ignoranti quem portum petat nullus suus ventus est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 71, 3","te":["sentido-de-vida","incertidumbre"]},{"i":"seneca-039","a":"seneca","t":"Hay que aprender mientras no sepas; y si creemos al proverbio, mientras vivas.","o":"Tamdiu discendum est quamdiu nescias; si proverbio credimus, quamdiu vivas.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 74, 3","te":["educacion","desarrollo-humano"]},{"i":"seneca-040","a":"seneca","t":"El dolor es leve si la opinión no le agrega nada.","o":"levis est dolor si nihil illi opinio adiecerit","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 74, 13","te":["sufrimiento","aceptacion"]},{"i":"seneca-041","a":"seneca","t":"El ocio sin estudio es muerte y sepultura del ser humano vivo.","o":"otium sine litteris mors est et hominis vivi sepultura","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 3","te":["sentido-de-vida","educacion"]},{"i":"seneca-042","a":"seneca","t":"El ser humano, cosa sagrada para el ser humano.","o":"Homo, sacra res homini","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 33","te":["sociedad","encuentro"]},{"i":"seneca-043","a":"seneca","t":"Sufre más de lo necesario quien sufre antes de lo necesario.","o":"Plus dolet quam necesse est qui ante dolet quam necesse est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 8","te":["angustia","sufrimiento","miedo"]},{"i":"seneca-044","a":"seneca","t":"No tenés que estar en otra parte, sino ser otro.","o":"non aliubi sis oportet sed alius","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 8","te":["transformacion-personal","cambio"]},{"i":"seneca-045","a":"seneca","t":"Considerá una gran cosa ser un solo hombre: ser siempre el mismo.","o":"Magnam rem puta unum hominem agere.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 33","te":["identidad","autenticidad"]},{"i":"seneca-046","a":"seneca","t":"No es que tengamos poco tiempo, sino que perdemos mucho.","o":"Non exiguum temporis habemus, sed multum perdidimus.","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"1, 3","te":["tiempo"]},{"i":"seneca-047","a":"seneca","t":"La vida, si sabés usarla, es larga.","o":"uita, si uti scias, longa est","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"2, 1","te":["tiempo","sentido-de-vida"]},{"i":"seneca-048","a":"seneca","t":"El mayor obstáculo para vivir es la espera, que depende del mañana y pierde el hoy.","o":"Maximum uiuendi impedimentum est exspectatio, quae pendet ex crastino, perdit hodiernum.","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"9, 1","te":["tiempo","presencia"]},{"i":"seneca-049","a":"seneca","t":"Todo lo que vendrá está en lo incierto: viví ahora.","o":"Omnia quae uentura sunt in incerto iacent: protinus uiue.","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"9, 1","te":["incertidumbre","presencia","tiempo"]},{"i":"seneca-050","a":"seneca","t":"A vivir hay que aprender toda la vida y, lo que quizás te asombre más, toda la vida hay que aprender a morir.","o":"uiuere tota uita discendum est et, quod magis fortasse miraberis, tota uita discendum est mori.","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"7, 3","te":["muerte","desarrollo-humano","sentido-de-vida"]},{"i":"seneca-051","a":"seneca","t":"Nada es menos propio de una persona atareada que vivir: no hay ciencia más difícil.","o":"Nihil minus est hominis occupati quam uiuere: nullius rei difficilior scientia est.","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"7, 3","te":["tiempo","trabajo","sentido-de-vida"]},{"i":"seneca-052","a":"seneca","t":"El mayor remedio de la ira es la demora.","o":"Maximum remedium irae mora est.","l":"la","ob":"Sobre la ira","an":"c. 41","u":"Libro 2, 29, 1","te":["ira","regulacion-emocional"]},{"i":"seneca-053","a":"seneca","t":"El fuego prueba el oro; la desgracia, a los valientes.","o":"Ignis aurum probat, miseria fortes uiros.","l":"la","ob":"Sobre la providencia","an":"c. 64","u":"5, 9","te":["resiliencia","sufrimiento"]},{"i":"marco-aurelio-001","a":"marco-aurelio","t":"Empezá la mañana diciéndote: hoy me voy a encontrar con el entrometido, el desagradecido, el arrogante, el mentiroso, el envidioso, el insociable.","o":"Begin the morning by saying to thyself, I shall meet with the busybody, the ungrateful, arrogant, deceitful, envious, unsocial.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 2, 1","te":["vinculos","aceptacion"]},{"i":"marco-aurelio-002","a":"marco-aurelio","t":"Recordá cuánto tiempo hace que venís postergando estas cosas.","o":"Remember how long thou hast been putting off these things","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 2, 4","te":["tiempo","cambio"]},{"i":"marco-aurelio-003","a":"marco-aurelio","t":"Nadie pierde otra vida que la que vive ahora, ni vive otra que la que ahora pierde.","o":"no man loses any other life than this which he now lives, nor lives any other than this which he now loses","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 2, 14","te":["tiempo","presencia","muerte"]},{"i":"marco-aurelio-004","a":"marco-aurelio","t":"Cada uno vive solo este momento presente, que es un punto indivisible; todo lo demás de su vida ya pasó o es incierto.","o":"every man lives only this present time, which is an indivisible point, and that all the rest of his life is either past or it is uncertain","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 3, 10","te":["presencia","tiempo","incertidumbre"]},{"i":"marco-aurelio-005","a":"marco-aurelio","t":"En ningún lugar encuentra una persona un retiro más tranquilo y libre de inquietud que en su propia alma.","o":"nowhere either with more quiet or more freedom from trouble does a man retire than into his own soul","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 3","te":["silencio","presencia","autoconocimiento"]},{"i":"marco-aurelio-006","a":"marco-aurelio","t":"El universo es transformación; la vida, opinión.","o":"The universe is transformation: life is opinion.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 3","te":["cambio","conciencia"]},{"i":"marco-aurelio-007","a":"marco-aurelio","t":"Quitá tu opinión y se quita la queja “me hicieron daño”.","o":"Take away thy opinion, and then there is taken away the complaint, \"I have been harmed.\"","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 7","te":["sufrimiento","aceptacion"]},{"i":"marco-aurelio-008","a":"marco-aurelio","t":"No actúes como si fueras a vivir diez mil años. La muerte pende sobre vos. Mientras vivas, mientras esté en tu poder, sé bueno.","o":"Do not act as if thou wert going to live ten thousand years. Death hangs over thee. While thou livest, while it is in thy power, be good.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 17","te":["muerte","tiempo","responsabilidad"]},{"i":"marco-aurelio-009","a":"marco-aurelio","t":"Cuántas molestias se ahorra quien no mira lo que dice, hace o piensa el vecino, sino solo lo que hace él mismo.","o":"How much trouble he avoids who does not look to see what his neighbor says or does or thinks, but only to what he does himself","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 18","te":["autoconocimiento","responsabilidad"]},{"i":"marco-aurelio-010","a":"marco-aurelio","t":"Sé como el promontorio contra el que rompen sin cesar las olas: se mantiene firme y amansa la furia del agua a su alrededor.","o":"Be like the promontory against which the waves continually break, but it stands firm and tames the fury of the water around it.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 49","te":["resiliencia","regulacion-emocional"]},{"i":"marco-aurelio-011","a":"marco-aurelio","t":"Como sean tus pensamientos habituales, así será el carácter de tu mente: el alma se tiñe de sus pensamientos.","o":"Such as are thy habitual thoughts, such also will be the character of thy mind; for the soul is dyed by the thoughts.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 5, 16","te":["conciencia","habitos","identidad"]},{"i":"marco-aurelio-012","a":"marco-aurelio","t":"La mejor manera de vengarte es no volverte como quien te hizo daño.","o":"The best way of avenging thyself is not to become like","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 6","te":["ira","vinculos"]},{"i":"marco-aurelio-013","a":"marco-aurelio","t":"Mirá hacia adentro. Adentro está la fuente del bien, y siempre brotará si siempre cavás.","o":"Look within. Within is the fountain of good, and it will ever bubble up, if thou wilt ever dig.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 59","te":["autoconocimiento","conciencia"]},{"i":"marco-aurelio-014","a":"marco-aurelio","t":"Si algo externo te duele, no es esa cosa la que te perturba, sino tu propio juicio sobre ella.","o":"If thou art pained by any external thing, it is not this thing that disturbs thee, but thy own judgment about it.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 8, 47","te":["sufrimiento","regulacion-emocional","conciencia"]},{"i":"marco-aurelio-015","a":"marco-aurelio","t":"No sigas discutiendo cómo debe ser un hombre bueno: selo.","o":"No longer talk at all about the kind of man that a good man ought to be, but be such.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 10, 16","te":["autenticidad","responsabilidad"]},{"i":"marco-aurelio-016","a":"marco-aurelio","t":"Considerá cuánto más dolor nos causan la ira y el fastidio por esos actos que los actos mismos.","o":"consider how much more pain is brought on us by the anger and vexation caused by such acts than by the acts themselves","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 11, 18","te":["ira","sufrimiento"]},{"i":"marco-aurelio-017","a":"marco-aurelio","t":"[Cada uno se ama más que a nadie, y sin embargo] valora menos su propia opinión sobre sí que la opinión de los demás.","o":"sets less value on his own opinion of himself than on the opinion of others","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 12, 4","te":["identidad","autenticidad"]},{"i":"marco-aurelio-018","a":"marco-aurelio","t":"Cuidate de no volverte un César, de no teñirte con ese tinte.","o":"Take care that thou art not made into a Caesar, that thou art not dyed with this dye","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 30","te":["poder","identidad"]},{"i":"marco-aurelio-019","a":"marco-aurelio","t":"La perfección del carácter consiste en vivir cada día como si fuera el último.","o":"The perfection of moral character consists in this, in passing every day as the last","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 69","te":["muerte","presencia"]},{"i":"marco-aurelio-020","a":"marco-aurelio","t":"Los seres humanos existen los unos para los otros. Enseñales, entonces, o soportalos.","o":"Men exist for the sake of one another. Teach them then, or bear with them.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 8, 59","te":["vinculos","aceptacion"]},{"i":"marco-aurelio-021","a":"marco-aurelio","t":"Lo que es obstáculo en el camino nos ayuda en ese camino.","o":"that which is an obstacle on the road helps us on this road","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 5, 20","te":["resiliencia","cambio"]},{"i":"marco-aurelio-022","a":"marco-aurelio","t":"Cuando te ofenda la desvergüenza de alguien, preguntate enseguida: ¿es posible que no haya desvergonzados en el mundo? No es posible.","o":"When thou art offended with any man's shameless conduct, immediately ask thyself, Is it possible, then, that shameless men should not be in the world? It is not possible.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 42","te":["aceptacion","ira"]},{"i":"marco-aurelio-023","a":"marco-aurelio","t":"Que no te perturbe lo que vendrá: llegarás a ello, si hace falta, con la misma razón que hoy usás para lo presente.","o":"Let not future things disturb thee, for thou wilt come to them, if it shall be necessary, having with thee the same reason which now thou usest for present things.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 8","te":["incertidumbre","angustia","presencia"]},{"i":"marco-aurelio-024","a":"marco-aurelio","t":"Puesto que es posible que dejes la vida en este mismo momento, regulá cada acto y cada pensamiento en consecuencia.","o":"Since it is possible that thou mayest depart from life this very moment, regulate every act and thought accordingly.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 2, 11","te":["muerte","presencia"]},{"i":"marco-aurelio-025","a":"marco-aurelio","t":"“Ocupate de pocas cosas si querés estar tranquilo”, dice el filósofo. Pero pensá si no sería mejor decir: hacé lo necesario.","o":"Occupy thyself with few things, says the philosopher, if thou wouldst be tranquil.--But consider if it would not be better to say, Do what is necessary","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 24","te":["presencia","trabajo"]},{"i":"marco-aurelio-026","a":"marco-aurelio","t":"Si alguien puede convencerme y mostrarme que no pienso o no actúo bien, cambiaré con gusto: busco la verdad, y nadie fue jamás dañado por ella.","o":"If any man is able to convince me and show me that I do not think or act right, I will gladly change; for I seek the truth, by which no man was ever injured.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 21","te":["verdad","cambio","transformacion-personal"]},{"i":"marco-aurelio-027","a":"marco-aurelio","t":"No malgastes lo que te queda de vida en pensamientos sobre los demás.","o":"Do not waste the remainder of thy life in thoughts about others","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 3, 4","te":["tiempo","autoconocimiento"]},{"i":"marco-aurelio-028","a":"marco-aurelio","t":"A la mañana, cuando te levantes de mala gana, tené presente este pensamiento: me levanto para hacer la obra de un ser humano.","o":"In the morning when thou risest unwillingly, let this thought be present,--I am rising to the work of a human being.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 5, 1","te":["trabajo","sentido-de-vida"]},{"i":"marco-aurelio-029","a":"marco-aurelio","t":"Es propio del ser humano amar incluso a quienes obran mal.","o":"It is peculiar to man to love even those who do wrong.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 22","te":["amor","compasion"]},{"i":"marco-aurelio-030","a":"marco-aurelio","t":"No te perturbes pensando en la totalidad de tu vida.","o":"Do not disturb thyself by thinking of the whole of thy life.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 8, 36","te":["angustia","presencia"]},{"i":"marco-aurelio-031","a":"marco-aurelio","t":"Cuando quieras alegrarte, pensá en las virtudes de quienes viven con vos.","o":"When thou wishest to delight thyself, think of the virtues of those who live with thee","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 48","te":["alegria","vinculos","gratitud"]},{"i":"marco-aurelio-032","a":"marco-aurelio","t":"Todas las cosas están entrelazadas unas con otras, y el lazo es sagrado.","o":"All things are implicated with one another, and the bond is holy","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 9","te":["conexion","naturaleza"]},{"i":"marco-aurelio-033","a":"marco-aurelio","t":"De la vida humana, el tiempo es un punto y la sustancia, un flujo.","o":"Of human life the time is a point, and the substance is in a flux","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 2, 17","te":["tiempo","cambio"]},{"i":"marco-aurelio-034","a":"marco-aurelio","t":"Si algo te resulta difícil de lograr, no pienses que es imposible para el ser humano.","o":"If a thing is difficult to be accomplished by thyself, do not think that it is impossible for man","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 19","te":["resiliencia"]},{"i":"marco-aurelio-035","a":"marco-aurelio","t":"No desprecies la muerte: aceptala de buen grado, porque también ella es una de las cosas que la naturaleza quiere.","o":"Do not despise death, but be well content with it, since this too is one of those things which nature wills.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 3","te":["muerte","aceptacion","naturaleza"]},{"i":"marco-aurelio-036","a":"marco-aurelio","t":"Si alguien se equivoca, enseñale con amabilidad y mostrale su error.","o":"If a man is mistaken, instruct him kindly and show him his error.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 10, 4","te":["comunicacion","compasion"]},{"i":"marco-aurelio-037","a":"marco-aurelio","t":"Considerá que también vos hacés muchas cosas mal, y que sos un ser humano como los demás.","o":"consider that thou also doest many things wrong, and that thou art a man like others","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 11, 18","te":["compasion","autoconocimiento"]},{"i":"marco-aurelio-038","a":"marco-aurelio","t":"Quien obra mal, obra mal contra sí mismo.","o":"He who does wrong does wrong against himself.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 4","te":["responsabilidad"]},{"i":"marco-aurelio-039","a":"marco-aurelio","t":"Tu opinión presente fundada en la comprensión, tu conducta presente orientada al bien común y tu disposición presente de contento con todo lo que sucede: eso basta.","o":"Thy present opinion founded on understanding, and thy present conduct directed to social good, and thy present disposition of contentment with everything which happens--that is enough.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 6","te":["presencia","aceptacion"]},{"i":"marco-aurelio-040","a":"marco-aurelio","t":"Que no te importe tener frío o calor si estás cumpliendo tu deber.","o":"Let it make no difference to thee whether thou art cold or warm, if thou art doing thy duty","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 2","te":["responsabilidad","trabajo"]},{"i":"marco-aurelio-041","a":"marco-aurelio","t":"Acostumbrate a atender con cuidado lo que dice otro y, en lo posible, a estar en la mente de quien habla.","o":"Accustom thyself to attend carefully to what is said by another, and as much as it is possible, be in the speaker's mind.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 53","te":["comunicacion","encuentro","atencion"]},{"i":"marco-aurelio-042","a":"marco-aurelio","t":"Borrá la fantasía. Detené el tirón de los hilos. Limitate al presente.","o":"Wipe out the imagination. Stop the pulling of the strings. Confine thyself to the present.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 29","te":["presencia","atencion"]},{"i":"marco-aurelio-043","a":"marco-aurelio","t":"A nadie le sucede nada que no esté formado por naturaleza para soportar.","o":"Nothing happens to any man which he is not formed by nature to bear.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 5, 18","te":["resiliencia","aceptacion"]},{"i":"marco-aurelio-044","a":"marco-aurelio","t":"Todo dura solo un día: lo que recuerda y lo recordado.","o":"Everything is only for a day, both that which remembers and that which is remembered.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 35","te":["tiempo","muerte"]},{"i":"marco-aurelio-045","a":"marco-aurelio","t":"Amá el oficio que aprendiste, por modesto que sea, y contentate con él.","o":"Love the art, poor as it may be, which thou hast learned, and be content with it","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 31","te":["trabajo","aceptacion"]},{"i":"marco-aurelio-046","a":"marco-aurelio","t":"El arte de vivir se parece más al del luchador que al del bailarín.","o":"The art of life is more like the wrestler's art than the dancer's","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 61","te":["resiliencia","sentido-de-vida"]},{"i":"marco-aurelio-047","a":"marco-aurelio","t":"Que haya serenidad frente a lo que viene de una causa externa.","o":"Let there be freedom from perturbations with respect to the things which come from the external cause","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 31","te":["regulacion-emocional","aceptacion"]},{"i":"marco-aurelio-048","a":"marco-aurelio","t":"Retirate en vos mismo. La razón que gobierna tiene esta naturaleza: se contenta consigo cuando obra con justicia, y así asegura la tranquilidad.","o":"Retire into thyself. The rational principle which rules has this nature, that it is content with itself when it does what is just, and so secures tranquillity.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 28","te":["silencio","autoconocimiento"]},{"i":"marco-aurelio-049","a":"marco-aurelio","t":"No es justo ofenderse con los demás: tu deber es cuidarlos y soportarlos con dulzura.","o":"it is no way right to be offended with men, but it is thy duty to care for them and to bear with them gently","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 3","te":["vinculos","compasion"]},{"i":"marco-aurelio-050","a":"marco-aurelio","t":"Qué ridículo y qué extraño a la vida es quien se sorprende de cualquier cosa que sucede en ella.","o":"How ridiculous and what a stranger he is who is surprised at anything which happens in life.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 12, 13","te":["aceptacion","existencia"]},{"i":"sigmund-freud-001","a":"sigmund-freud","t":"La intención de que el ser humano sea “feliz” no está contenida en el plan de la “Creación”.","o":"die Absicht, daß der Mensch \"glücklich\" sei, ist im Plan der \"Schöpfung\" nicht enthalten","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["felicidad","sufrimiento"]},{"i":"sigmund-freud-002","a":"sigmund-freud","t":"El sufrimiento nos amenaza desde tres lados: desde el propio cuerpo, condenado a la decadencia y la disolución, que ni siquiera puede prescindir del dolor y la angustia como señales de alarma; desde el mundo exterior, que puede abatirse sobre nosotros con fuerzas hiperpotentes, implacables y destructivas; y por último, desde los vínculos con otros seres humanos.","o":"Von drei Seiten droht das Leiden, vom eigenen Körper her, der, zu Verfall und Auflösung bestimmt, sogar Schmerz und Angst als Warnungssignale nicht entbehren kann, von der Außenwelt, die mit übermächtigen, unerbittlichen, zerstörenden Kräften gegen uns wüten kann, und endlich aus den Beziehungen zu anderen Menschen.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["sufrimiento","vinculos","cuerpo"]},{"i":"sigmund-freud-003","a":"sigmund-freud","t":"El sufrimiento que proviene de esta fuente [los vínculos] lo sentimos quizás más dolorosamente que cualquier otro.","o":"Das Leiden, das aus dieser Quelle stammt, empfinden wir vielleicht schmerzlicher als jedes andere","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["sufrimiento","vinculos"]},{"i":"sigmund-freud-004","a":"sigmund-freud","t":"Nunca estamos más desprotegidos frente al sufrimiento que cuando amamos; nunca más desamparadamente infelices que cuando perdimos al objeto amado o su amor.","o":"Niemals sind wir ungeschützter gegen das Leiden, als wenn wir lieben, niemals hilfloser unglücklich, als wenn wir das geliebte Objekt oder seine Liebe verloren haben.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["amor","perdida","duelo"]},{"i":"sigmund-freud-005","a":"sigmund-freud","t":"La vida, tal como nos es impuesta, resulta demasiado pesada: nos trae demasiados dolores, desengaños, tareas insolubles.","o":"Das Leben, wie es uns auferlegt ist, ist zu schwer für uns, es bringt uns zuviel Schmerzen, Enttäuschungen, unlösbare Aufgaben.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["sufrimiento","existencia"]},{"i":"sigmund-freud-006","a":"sigmund-freud","t":"El ser humano se ha convertido, por así decir, en una especie de dios con prótesis: bastante magnífico cuando se coloca todos sus órganos auxiliares, pero estos no se le han integrado.","o":"Der Mensch ist sozusagen eine Art Prothesengott geworden, recht großartig, wenn er alle seine Hilfsorgane anlegt, aber sie sind nicht mit ihm verwachsen","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 3","te":["tecnologia","cultura"]},{"i":"sigmund-freud-007","a":"sigmund-freud","t":"La felicidad, en ese sentido moderado en que se la reconoce posible, es un problema de la economía libidinal de cada individuo.","o":"Das Glück in jenem ermäßigten Sinn, in dem es als möglich erkannt wird, ist ein Problem der individuellen Libidoökonomie.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["felicidad","deseo"]},{"i":"sigmund-freud-008","a":"sigmund-freud","t":"El goce de la belleza tiene un carácter sensorial particular, suavemente embriagador.","o":"Der Genuß an der Schönheit hat einen besonderen, milde berauschenden Empfindungscharakter.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["alegria","cultura"]},{"i":"sigmund-freud-009","a":"sigmund-freud","t":"La utilidad de la belleza no es evidente, su necesidad cultural no se ve, y sin embargo la cultura no podría prescindir de ella.","o":"Ein Nutzen der Schönheit liegt nicht klar zutage, ihre kulturelle Notwendigkeit ist nicht einzusehen, und doch könnte man sie in der Kultur nicht vermissen.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["cultura"]},{"i":"sigmund-freud-010","a":"sigmund-freud","t":"Esta actitud estética ante la meta de la vida protege poco contra los sufrimientos que amenazan, pero puede compensar muchas cosas.","o":"Diese ästhetische Einstellung zum Lebensziel bietet wenig Schutz gegen drohende Leiden, vermag aber für vieles zu entschädigen.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["sufrimiento","cultura"]},{"i":"sigmund-freud-011","a":"sigmund-freud","t":"Quien emprende este camino hacia la felicidad [rehacer el mundo según sus deseos] con una rebeldía desesperada, por lo general no logrará nada: la realidad es demasiado fuerte para él.","o":"Wer in verzweifelter Empörung diesen Weg zum Glück einschlägt, wird in der Regel nichts erreichen; die Wirklichkeit ist zu stark für ihn.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["felicidad","deseo"]},{"i":"sigmund-freud-012","a":"sigmund-freud","t":"La tarea es desplazar las metas pulsionales de manera que la frustración que impone el mundo exterior no pueda alcanzarlas.","o":"Die zu lösende Aufgabe ist, die Triebziele solcherart zu verlegen, daß sie von der Versagung der Außenwelt nicht getroffen werden können.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["deseo","sufrimiento"]},{"i":"sigmund-freud-013","a":"sigmund-freud","t":"Y sin embargo, las personas valoran poco el trabajo como camino hacia la felicidad.","o":"Und dennoch wird Arbeit als Weg zum Glück von den Menschen wenig geschätzt.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["trabajo","felicidad"]},{"i":"sigmund-freud-014","a":"sigmund-freud","t":"El ser humano civilizado cambió una parte de posibilidad de felicidad por una parte de seguridad.","o":"Der Kulturmensch hat für ein Stück Glücksmöglichkeit ein Stück Sicherheit eingetauscht.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 5","te":["cultura","felicidad","sociedad"]},{"i":"sigmund-freud-015","a":"sigmund-freud","t":"La cultura tiene que movilizarlo todo para poner límites a las pulsiones agresivas de los seres humanos.","o":"Die Kultur muß alles aufbieten, um den Aggressionstrieben der Menschen Schranken zu setzen","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 5","te":["cultura","ira","sociedad"]},{"i":"sigmund-freud-016","a":"sigmund-freud","t":"Siempre es posible ligar amorosamente entre sí a una multitud mayor de personas, con tal de que queden otras para manifestarles la agresión.","o":"Es ist immer möglich, eine größere Menge von Menschen in Liebe aneinander zu binden, wenn nur andere für die Äußerung der Aggression übrigbleiben.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 5","te":["sociedad","ira","poder"]},{"i":"sigmund-freud-017","a":"sigmund-freud","t":"Las pasiones pulsionales son más fuertes que los intereses racionales.","o":"triebhafte Leidenschaften sind stärker als vernünftige Interessen","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 5","te":["deseo","sociedad"]},{"i":"sigmund-freud-018","a":"sigmund-freud","t":"La agresión es introyectada, interiorizada, en verdad devuelta al lugar de donde vino: vuelta contra el propio yo.","o":"Die Aggression wird introjiziert, verinnerlicht, eigentlich aber dorthin zurückgeschickt, woher sie gekommen ist, also gegen das eigene Ich gewendet.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 7","te":["culpa","ira","inconsciente"]},{"i":"sigmund-freud-019","a":"sigmund-freud","t":"A la tensión entre el severo superyó y el yo que le está sometido la llamamos conciencia de culpa; se manifiesta como necesidad de castigo.","o":"Die Spannung zwischen dem gestrengen Über-Ich und dem ihm unterworfenen Ich heißen wir Schuldbewußtsein; sie äußert sich als Strafbedürfnis.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 7","te":["culpa","inconsciente"]},{"i":"sigmund-freud-020","a":"sigmund-freud","t":"Lo malo es, al principio, aquello por lo cual se nos amenaza con la pérdida del amor; por angustia ante esa pérdida hay que evitarlo.","o":"Das Böse ist also anfänglich dasjenige, wofür man mit Liebesverlust bedroht wird; aus Angst vor diesem Verlust muß man es vermeiden.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 7","te":["culpa","miedo","amor"]},{"i":"sigmund-freud-021","a":"sigmund-freud","t":"La agresión de la conciencia moral conserva la agresión de la autoridad.","o":"Die Aggression des Gewissens konserviert die Aggression der Autorität.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 7","te":["culpa","poder"]},{"i":"sigmund-freud-022","a":"sigmund-freud","t":"Las religiones, al menos, nunca desconocieron el papel del sentimiento de culpa en la cultura.","o":"Die Religionen wenigstens haben die Rolle des Schuldgefühls in der Kultur nie verkannt.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 8","te":["culpa","cultura","trascendencia"]},{"i":"sigmund-freud-023","a":"sigmund-freud","t":"Eros y Ananké [amor y necesidad] se convirtieron también en los padres de la cultura humana.","o":"Eros und Ananke sind auch die Eltern der menschlichen Kultur geworden.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 4","te":["amor","cultura"]},{"i":"sigmund-freud-024","a":"sigmund-freud","t":"[Mi propósito era] presentar el sentimiento de culpa como el problema más importante del desarrollo cultural.","o":"das Schuldgefühl als das wichtigste Problem der Kulturentwicklung hinzustellen","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 8","te":["culpa","cultura"]},{"i":"sigmund-freud-025","a":"sigmund-freud","t":"No sabría indicar una necesidad de la infancia tan intensa como la de la protección paterna.","o":"Ein ähnlich starkes Bedürfnis aus der Kindheit wie das nach dem Vaterschutz wüßte ich nicht anzugeben.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 1","te":["familia","infancia"]},{"i":"sigmund-freud-026","a":"sigmund-freud","t":"El beneficio del orden es innegable: permite al ser humano aprovechar mejor el espacio y el tiempo, mientras ahorra sus fuerzas psíquicas.","o":"Die Wohltat der Ordnung ist ganz unleugbar, sie ermöglicht dem Menschen die beste Ausnützung von Raum und Zeit, während sie seine psychischen Kräfte schont.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 3","te":["habitos","cultura"]},{"i":"sigmund-freud-027","a":"sigmund-freud","t":"El orden es una especie de compulsión de repetición que, establecida una vez, decide cuándo, dónde y cómo debe hacerse algo.","o":"Die Ordnung ist eine Art Wiederholungszwang, die durch einmalige Einrichtung entscheidet, wann, wo und wie etwas getan werden soll","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 3","te":["habitos","inconsciente"]},{"i":"sigmund-freud-028","a":"sigmund-freud","t":"El amor de meta inhibida fue en su origen amor plenamente sensual, y lo sigue siendo en lo inconsciente del ser humano.","o":"Die zielgehemmte Liebe war eben ursprünglich vollsinnliche Liebe und ist es im Unbewußten des Menschen noch immer.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 4","te":["amor","inconsciente","deseo"]},{"i":"sigmund-freud-029","a":"sigmund-freud","t":"La voz del intelecto es baja, pero no descansa hasta hacerse oír.","o":"die Stimme des Intellekts ist leise, aber sie ruht nicht, ehe sie sich Gehör geschafft hat","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 9","te":["verdad","conciencia"]},{"i":"sigmund-freud-030","a":"sigmund-freud","t":"No, nuestra ciencia no es una ilusión. Pero sería una ilusión creer que podríamos obtener de otra parte lo que ella no puede darnos.","o":"Nein, unsere Wissenschaft ist keine Illusion. Eine Illusion aber wäre es zu glauben, daß wir anderswoher bekommen könnten, was sie uns nicht geben kann.","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 9","te":["verdad","conocimiento"]},{"i":"sigmund-freud-031","a":"sigmund-freud","t":"El ser humano no puede seguir siendo niño para siempre: tiene que salir, finalmente, a la “vida hostil”.","o":"Der Mensch kann nicht ewig Kind bleiben, er muß endlich hinaus ins \"feindliche Leben\".","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 8","te":["desarrollo-humano","infancia","responsabilidad"]},{"i":"sigmund-freud-032","a":"sigmund-freud","t":"No hay ninguna instancia por encima de la razón.","o":"Es gibt keine Instanz über der Vernunft.","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 4","te":["verdad"]},{"i":"sigmund-freud-033","a":"sigmund-freud","t":"Como estamos dispuestos a renunciar a buena parte de nuestros deseos infantiles, podemos soportar que algunas de nuestras expectativas resulten ser ilusiones.","o":"Da wir bereit sind, auf ein gutes Stück unserer infantilen Wünsche zu verzichten, können wir es vertragen, wenn sich einige unserer Erwartungen als Illusionen herausstellen.","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 9","te":["deseo","aceptacion","desarrollo-humano"]},{"i":"sigmund-freud-034","a":"sigmund-freud","t":"Podemos insistir cuanto queramos en que el intelecto humano carece de fuerza frente a la vida pulsional, y tener razón.","o":"Wir mögen noch so oft betonen, der menschliche Intellekt sei kraftlos im Vergleich zum menschlichen Triebleben, und recht damit haben.","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 9","te":["deseo","conciencia"]},{"i":"sigmund-freud-035","a":"sigmund-freud","t":"El yo es, ante todo, un yo corporal: no es solo un ser de superficie, sino él mismo la proyección de una superficie.","o":"Das Ich ist vor allem ein körperliches, es ist nicht nur ein Oberflächenwesen, sondern selbst die Projektion einer Oberfläche.","l":"de","ob":"El yo y el ello","an":"1923","u":"Capítulo 2","te":["identidad","cuerpo"]},{"i":"sigmund-freud-036","a":"sigmund-freud","t":"El yo es la verdadera sede de la angustia.","o":"Das Ich ist ja die eigentliche Angststätte.","l":"de","ob":"El yo y el ello","an":"1923","u":"Capítulo 5","te":["angustia","identidad"]},{"i":"sigmund-freud-037","a":"sigmund-freud","t":"[Vemos] al mismo yo como una pobre criatura, sometida a tres servidumbres y que, por eso, sufre la amenaza de tres peligros.","o":"dasselbe Ich als armes Ding, welches unter dreierlei Dienstbarkeiten steht und demzufolge unter den Drohungen von dreierlei Gefahren leidet","l":"de","ob":"El yo y el ello","an":"1923","u":"Capítulo 5","te":["identidad","sufrimiento"]},{"i":"sigmund-freud-038","a":"sigmund-freud","t":"El psicoanálisis es un instrumento que debe permitirle al yo la conquista progresiva del ello.","o":"Die Psychoanalyse ist ein Werkzeug, welches dem Ich die fortschreitende Eroberung des Es ermöglichen soll.","l":"de","ob":"El yo y el ello","an":"1923","u":"Capítulo 5","te":["terapia","inconsciente"]},{"i":"sigmund-freud-039","a":"sigmund-freud","t":"[El yo] ni siquiera es dueño en su propia casa, sino que depende de escasas noticias sobre lo que ocurre de manera inconsciente en su vida anímica.","o":"daß es nicht einmal Herr ist im eigenen Hause, sondern auf kärgliche Nachrichten angewiesen bleibt von dem, was unbewußt in seinem Seelenleben vorgeht","l":"de","ob":"Conferencias de introducción al psicoanálisis","an":"1917","u":"Capítulo 18","te":["inconsciente","identidad","autoconocimiento"]},{"i":"sigmund-freud-040","a":"sigmund-freud","t":"Las palabras fueron en su origen magia, y la palabra conserva todavía hoy mucho de su antiguo poder mágico.","o":"Worte waren ursprünglich Zauber, und das Wort hat noch heute viel von seiner alten Zauberkraft bewahrt.","l":"de","ob":"Conferencias de introducción al psicoanálisis","an":"1917","u":"Capítulo 1","te":["comunicacion","terapia"]},{"i":"sigmund-freud-041","a":"sigmund-freud","t":"Con palabras una persona puede hacer dichosa a otra o empujarla a la desesperación.","o":"Durch Worte kann ein Mensch den anderen selig machen oder zur Verzweiflung treiben","l":"de","ob":"Conferencias de introducción al psicoanálisis","an":"1917","u":"Capítulo 1","te":["comunicacion","vinculos"]},{"i":"sigmund-freud-042","a":"sigmund-freud","t":"En el tratamiento analítico no ocurre otra cosa que un intercambio de palabras entre el analizado y el médico.","o":"In der analytischen Behandlung geht nichts anderes vor als ein Austausch von Worten zwischen dem Analysierten und dem Arzt.","l":"de","ob":"Conferencias de introducción al psicoanálisis","an":"1917","u":"Capítulo 1","te":["terapia","comunicacion"]},{"i":"sigmund-freud-043","a":"sigmund-freud","t":"Los sentimientos hostiles significan un lazo afectivo tanto como los tiernos.","o":"Die feindlichen Gefühle bedeuten ebenso eine Gefühlsbindung wie die zärtlichen","l":"de","ob":"Conferencias de introducción al psicoanálisis","an":"1917","u":"Capítulo 27","te":["vinculos","ira","amor"]},{"i":"sigmund-freud-047","a":"sigmund-freud","t":"Donde era ello, ha de advenir yo. Es un trabajo de cultura, como la desecación del Zuiderzee.","o":"Wo Es war, soll Ich werden. Es ist Kulturarbeit etwa wie die Trockenlegung der Zuydersee.","l":"de","ob":"Nuevas conferencias de introducción al psicoanálisis","an":"1933","u":"Capítulo 3","te":["inconsciente","terapia","transformacion-personal"]},{"i":"sigmund-freud-044","a":"sigmund-freud","t":"La interpretación de los sueños es la vía regia hacia el conocimiento de lo inconsciente en la vida anímica.","o":"Die Traumdeutung aber ist die Via regia zur Kenntnis des Unbewußten im Seelenleben.","l":"de","ob":"La interpretación de los sueños","an":"1900","u":"Capítulo 7","te":["suenos","inconsciente"]},{"i":"sigmund-freud-045","a":"sigmund-freud","t":"El sueño es el cumplimiento (disfrazado) de un deseo (sofocado, reprimido).","o":"Der Traum ist die (verkleidete) Erfüllung eines (unterdrückten, verdrängten) Wunsches","l":"de","ob":"La interpretación de los sueños","an":"1900","u":"Capítulo 4","te":["suenos","deseo","inconsciente"]},{"i":"sigmund-freud-046","a":"sigmund-freud","t":"La meta de toda vida es la muerte.","o":"Das Ziel alles Lebens ist der Tod","l":"de","ob":"Más allá del principio del placer","an":"1920","u":"Capítulo 5","te":["muerte"]},{"i":"sigmund-freud-050","a":"sigmund-freud","t":"El psicoanálisis consideró desde el comienzo que ese destino [que parece perseguir a algunas personas] es en gran parte autoprovocado y está determinado por influencias de la primera infancia.","o":"die Psychoanalyse hat vom Anfang an solches Schicksal für zum großen Teil selbstbereitet und durch frühinfantile Einflüsse determiniert gehalten","l":"de","ob":"Más allá del principio del placer","an":"1920","u":"Capítulo 3","te":["repeticion","infancia","inconsciente"]},{"i":"sigmund-freud-048","a":"sigmund-freud","t":"Nuestras enfermas histéricas sufren de reminiscencias.","o":"Unsere hysterisch Kranken leiden an Reminiszenzen.","l":"de","ob":"Sobre psicoanálisis (Cinco conferencias)","an":"1910","u":"Capítulo 1","te":["sufrimiento","memoria","trauma"]},{"i":"sigmund-freud-049","a":"sigmund-freud","t":"La interpretación de los sueños es, en realidad, la vía regia hacia el conocimiento de lo inconsciente, el fundamento más seguro del psicoanálisis.","o":"Die Traumdeutung ist in Wirklichkeit die Via Regia zur Kenntnis des Unbewußten, die sicherste Grundlage der Psychoanalyse","l":"de","ob":"Sobre psicoanálisis (Cinco conferencias)","an":"1910","u":"Capítulo 3","te":["suenos","inconsciente"]},{"i":"william-james-001","a":"william-james","t":"El hábito es así el enorme volante de la sociedad, su más preciado agente conservador.","o":"Habit is thus the enormous fly-wheel of society, its most precious conservative agent.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","sociedad"]},{"i":"william-james-002","a":"william-james","t":"Lo importante en toda educación es hacer de nuestro sistema nervioso un aliado y no un enemigo.","o":"make our nervous system our ally instead of our enemy","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","educacion"]},{"i":"william-james-003","a":"william-james","t":"Si los jóvenes comprendieran qué pronto se convertirán en meros manojos ambulantes de hábitos, prestarían más atención a su conducta mientras todavía son moldeables.","o":"Could the young but realize how soon they will become mere walking bundles of habits, they would give more heed to their conduct while in the plastic state.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","desarrollo-humano"]},{"i":"william-james-004","a":"william-james","t":"Estamos hilando nuestro propio destino, bueno o malo, y no hay manera de deshacerlo.","o":"We are spinning our own fates, good or evil, and never to be undone.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","responsabilidad"]},{"i":"william-james-005","a":"william-james","t":"Cada mínimo trazo de virtud o de vicio deja su cicatriz, por pequeña que sea.","o":"Every smallest stroke of virtue or of vice leaves its never so little scar.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","identidad"]},{"i":"william-james-006","a":"william-james","t":"No permitas ninguna excepción hasta que el nuevo hábito esté firmemente arraigado en tu vida.","o":"Never suffer an exception to occur till the new habit is securely rooted in your life","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","cambio"]},{"i":"william-james-007","a":"william-james","t":"Aprovechá la primera oportunidad posible para actuar según cada resolución que tomes.","o":"Seize the very first possible opportunity to act on every resolution you make","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","cambio"]},{"i":"william-james-008","a":"william-james","t":"Mantené viva en vos la capacidad de esfuerzo con un pequeño ejercicio gratuito cada día.","o":"Keep the faculty of effort alive in you by a little gratuitous exercise every day","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","voluntad"]},{"i":"william-james-009","a":"william-james","t":"[La conciencia] no está hecha de piezas articuladas: fluye. “Río” o “corriente” son las metáforas que mejor la describen.","o":"It is nothing jointed; it flows. A 'river' or a 'stream' are the metaphors by which it is most naturally described.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 9","te":["conciencia"]},{"i":"william-james-010","a":"william-james","t":"Llamémosla corriente del pensamiento, de la conciencia o de la vida subjetiva.","o":"let us call it the stream of thought, of consciousness, or of subjective life","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 9","te":["conciencia"]},{"i":"william-james-011","a":"william-james","t":"Todo pensamiento tiende a formar parte de una conciencia personal.","o":"Every thought tends to be part of a personal consciousness.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 9","te":["conciencia","identidad"]},{"i":"william-james-012","a":"william-james","t":"Ningún estado, una vez pasado, puede repetirse idéntico a lo que fue.","o":"no state once gone can recur and be identical with what it was before","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 9","te":["conciencia","cambio"]},{"i":"william-james-013","a":"william-james","t":"Mi experiencia es aquello a lo que acepto prestar atención.","o":"My experience is what I agree to attend to.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion","conciencia"]},{"i":"william-james-014","a":"william-james","t":"Sin un interés selectivo, la experiencia es un caos absoluto.","o":"without selective interest, experience is an utter chaos","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion","conciencia"]},{"i":"william-james-015","a":"william-james","t":"Todo el mundo sabe qué es la atención.","o":"Every one knows what attention is.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion"]},{"i":"william-james-016","a":"william-james","t":"La capacidad de traer de vuelta voluntariamente una atención que se dispersa, una y otra vez, es la raíz misma del juicio, del carácter y de la voluntad.","o":"the faculty of voluntarily bringing back a wandering attention, over and over again, is the very root of judgment, character, and will","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion","voluntad","presencia"]},{"i":"william-james-017","a":"william-james","t":"Una persona tiene tantos “yo” sociales como individuos la reconocen.","o":"a man has as many social selves as there are individuals who recognize him","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 10","te":["identidad","vinculos"]},{"i":"william-james-018","a":"william-james","t":"En su sentido más amplio, el “sí mismo” de una persona es la suma total de todo lo que puede llamar suyo.","o":"a man's Self is the sum total of all that he","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 10","te":["identidad"]},{"i":"william-james-019","a":"william-james","t":"Autoestima = éxito / pretensiones.","o":"Self-esteem = Success/ Pretensions.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 10","te":["autoestima","identidad"]},{"i":"william-james-020","a":"william-james","t":"Renunciar a las pretensiones es un alivio tan bendito como verlas satisfechas.","o":"To give up pretensions is as blessed a relief as to get them gratified","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 10","te":["autoestima","aceptacion"]},{"i":"william-james-021","a":"william-james","t":"El bebé, asaltado a la vez por ojos, oídos, nariz, piel y entrañas, lo siente todo como una gran confusión floreciente y zumbante.","o":"The baby, assailed by eyes, ears, nose, skin, and entrails at once, feels it all as one great blooming, buzzing confusion","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 13","te":["desarrollo-humano","infancia"]},{"i":"william-james-045","a":"william-james","t":"Solo el interés da acento y énfasis, luz y sombra, fondo y primer plano.","o":"Interest alone gives accent and emphasis, light and shade, background and foreground","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion","conciencia"]},{"i":"william-james-048","a":"william-james","t":"Solo las cosas que noto le dan forma a mi mente.","o":"Only those items which I","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion","conciencia"]},{"i":"william-james-049","a":"william-james","t":"El infierno que nos espera en el más allá, del que habla la teología, no es peor que el infierno que nos fabricamos en este mundo al moldear habitualmente nuestro carácter de la manera equivocada.","o":"The hell to be endured hereafter, of which theology tells, is no worse than the hell we make for ourselves in this world by habitually fashioning our characters in the wrong way.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","sufrimiento","responsabilidad"]},{"i":"william-james-022","a":"william-james","t":"El arte de ser sabio es el arte de saber qué pasar por alto.","o":"the art of being wise is the art of knowing what to overlook","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 22","te":["atencion","conocimiento"]},{"i":"william-james-023","a":"william-james","t":"Nos sentimos tristes porque lloramos, enojados porque golpeamos, asustados porque temblamos.","o":"we feel sorry because we cry, angry because we strike, afraid because we tremble","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 25","te":["emociones","cuerpo"]},{"i":"william-james-024","a":"william-james","t":"Una emoción humana puramente desencarnada no es nada.","o":"A purely disembodied human emotion is a nonentity.","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 25","te":["emociones","cuerpo"]},{"i":"william-james-025","a":"william-james","t":"Si queremos vencer tendencias emocionales indeseadas, debemos atravesar con asiduidad, y al principio a sangre fría, los movimientos externos de las disposiciones contrarias que preferimos cultivar.","o":"we must assiduously, and in the first instance cold-bloodedly, go through the","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 25","te":["regulacion-emocional","habitos"]},{"i":"william-james-026","a":"william-james","t":"El logro esencial de la voluntad es atender a un objeto difícil y sostenerlo firme ante la mente.","o":"to_ ATTEND _to a difficult object and hold it fast before the mind","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 26","te":["atencion","voluntad"]},{"i":"william-james-047","a":"william-james","t":"Así como el arte de leer (a partir de cierta etapa de la formación) es el arte de saltear…","o":"As the art of reading (after a certain stage in one's education) is the art of skipping","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 22","te":["educacion","atencion"]},{"i":"william-james-050","a":"william-james","t":"El genio, en verdad, no es mucho más que la capacidad de percibir de una manera no habitual.","o":"Genius, in truth, means little more than the faculty of perceiving in an unhabitual way.","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 19","te":["creatividad","conciencia"]},{"i":"william-james-041","a":"william-james","t":"[La religión significará para nosotros] los sentimientos, actos y experiencias de las personas en su soledad, en la medida en que se perciben en relación con lo que consideren divino.","o":"the feelings, acts, and experiences of individual men in their solitude, so far as they apprehend themselves to stand in relation to whatever they may consider the divine","l":"en","ob":"Las variedades de la experiencia religiosa","an":"1902","u":"Conferencia 2","te":["trascendencia","soledad"]},{"i":"william-james-042","a":"william-james","t":"[Nuestra conciencia de vigilia] no es más que un tipo especial de conciencia; a su alrededor, separadas por la más fina de las pantallas, hay formas potenciales de conciencia completamente distintas.","o":"is but one special type of consciousness, whilst all about it, parted from it by the filmiest of screens, there lie potential forms of consciousness entirely different","l":"en","ob":"Las variedades de la experiencia religiosa","an":"1902","u":"Conferencia 13","te":["conciencia","trascendencia"]},{"i":"william-james-043","a":"william-james","t":"El mundo de nuestra conciencia presente es solo uno entre muchos mundos de conciencia que existen.","o":"the world of our present consciousness is only one out of many worlds of consciousness that exist","l":"en","ob":"Las variedades de la experiencia religiosa","an":"1902","u":"Conferencia 20","te":["conciencia"]},{"i":"william-james-044","a":"william-james","t":"La religión, sea lo que sea, es la reacción total de una persona ante la vida.","o":"Religion, whatever it is, is a man's total reaction upon life","l":"en","ob":"Las variedades de la experiencia religiosa","an":"1902","u":"Conferencia 2","te":["trascendencia","sentido-de-vida"]},{"i":"william-james-038","a":"william-james","t":"La verdad de una idea no es una propiedad estancada que le es inherente. La verdad le sucede a una idea: se vuelve verdadera, los acontecimientos la hacen verdadera.","o":"The truth of an idea is not a stagnant property inherent in it. Truth HAPPENS to an idea. It BECOMES true, is MADE true by events.","l":"en","ob":"Pragmatismo","an":"1907","u":"Conferencia 6","te":["verdad"]},{"i":"william-james-039","a":"william-james","t":"Como seres humanos, podemos ser mentes sanas un día y almas enfermas al siguiente.","o":"as human beings we can be healthy minds on one day and sick souls on the next","l":"en","ob":"Pragmatismo","an":"1907","u":"Conferencia 8","te":["salud-mental","sufrimiento"]},{"i":"william-james-040","a":"william-james","t":"Cualquiera sea el universo en que crea un profesor, tiene que ser al menos un universo que se preste a discursos largos.","o":"Whatever universe a professor believes in must at any rate be a universe that lends itself to lengthy discourse.","l":"en","ob":"Pragmatismo","an":"1907","u":"Conferencia 1","te":["educacion","humor"]},{"i":"william-james-027","a":"william-james","t":"Dondequiera que un proceso vital le comunica entusiasmo a quien lo vive, allí la vida se vuelve verdaderamente significativa.","o":"Wherever a process of life communicates an eagerness to him who lives it, there the life becomes genuinely significant.","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«On A Certain Blindness In Human Beings»","te":["sentido-de-vida","alegria"]},{"i":"william-james-028","a":"william-james","t":"Ni toda la verdad ni todo el bien se revelan a un solo observador.","o":"neither the whole of truth nor the whole of good is revealed to any single observer","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«On A Certain Blindness In Human Beings»","te":["verdad","encuentro"]},{"i":"william-james-029","a":"william-james","t":"La ceguera que todos padecemos respecto de los sentimientos de criaturas y personas distintas de nosotros.","o":"the blindness with which we all are afflicted in regard to the feelings of creatures and people different from ourselves","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«On A Certain Blindness In Human Beings»","te":["empatia","vinculos"]},{"i":"william-james-030","a":"william-james","t":"La acción parece seguir al sentimiento, pero en realidad acción y sentimiento van juntos.","o":"Action seems to follow feeling, but really action and feeling go together","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«The Gospel Of Relaxation»","te":["emociones","regulacion-emocional"]},{"i":"william-james-031","a":"william-james","t":"El camino voluntario soberano hacia la alegría, si perdimos la espontánea, es enderezarnos con alegría, mirar alrededor con alegría [y actuar y hablar como si ya estuviera allí].","o":"the sovereign voluntary path to cheerfulness, if our spontaneous cheerfulness be lost, is to sit up cheerfully, to look round cheerfully","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«The Gospel Of Relaxation»","te":["alegria","regulacion-emocional"]},{"i":"william-james-032","a":"william-james","t":"Somos seres prácticos, cada uno con funciones y deberes limitados que cumplir.","o":"We are practical beings, each of us with limited functions and duties to perform.","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«On A Certain Blindness In Human Beings»","te":["trabajo","identidad"]},{"i":"william-james-046","a":"william-james","t":"Cada recaída es como dejar caer un ovillo que uno estaba enrollando con cuidado.","o":"Each lapse is like the letting fall of a ball of string which one is carefully winding up","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«The Laws Of Habit»","te":["habitos","cambio"]},{"i":"william-james-033","a":"william-james","t":"No le tengas miedo a la vida. Creé que la vida vale la pena, y tu creencia ayudará a crear el hecho.","o":"Be not afraid of life. Believe that life","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«Is Life Worth Living?»","te":["sentido-de-vida","miedo","esperanza"]},{"i":"william-james-034","a":"william-james","t":"Solo arriesgándonos de una hora a la otra vivimos realmente.","o":"It is only by risking our persons from one hour to another that we live at all.","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«Is Life Worth Living?»","te":["libertad","incertidumbre"]},{"i":"william-james-035","a":"william-james","t":"A menudo, nuestra fe anticipada en un resultado incierto es lo único que hace que el resultado se cumpla.","o":"our faith beforehand in an uncertified result","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«Is Life Worth Living?»","te":["esperanza","incertidumbre"]},{"i":"william-james-036","a":"william-james","t":"Nuestra naturaleza pasional no solo puede legítimamente, sino que debe, decidir entre proposiciones [cuando se trata de una opción genuina que el intelecto no puede zanjar].","o":"Our passional nature not only lawfully may, but must, decide an option between propositions","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«The Will To Believe»","te":["deseo","verdad","libertad"]},{"i":"william-james-037","a":"william-james","t":"Podemos decir que esta vida vale la pena, ya que es lo que hacemos de ella, desde el punto de vista moral.","o":"This life is worth living, we can say,","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«Is Life Worth Living?»","te":["sentido-de-vida","responsabilidad"]},{"i":"william-james-051","a":"william-james","t":"Una regla de pensamiento que me impidiera absolutamente reconocer ciertos tipos de verdad, si esas verdades realmente existieran, [sería una regla irracional].","o":"a rule of thinking which would absolutely prevent me from acknowledging certain kinds of truth if those kinds of truth were really there","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«The Will To Believe»","te":["verdad","conocimiento"]},{"i":"epicteto-029","a":"epicteto","t":"Son las dificultades las que muestran quiénes son las personas.","o":"It is circumstances (difficulties) which show what men are.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we should struggle with circumstances»","te":["resiliencia","identidad"]},{"i":"epicteto-030","a":"epicteto","t":"Nada grande, decía Epicteto, se produce de golpe: ni siquiera la uva o el higo.","o":"Nothing great, said Epictetus, is produced suddenly, since not even the grape or the fig is.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«What philosophy promises»","te":["cambio","habitos"]},{"i":"epicteto-031","a":"epicteto","t":"La materia del arte de vivir es la vida de cada uno.","o":"so the matter of the art of living is each man's life.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«What philosophy promises»","te":["sentido-de-vida","responsabilidad"]},{"i":"epicteto-032","a":"epicteto","t":"¿Dónde está el bien? En la voluntad. ¿Dónde está el mal? En la voluntad.","o":"Where is the good? In the will. Where is the evil? In the will.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«That we do not strive to use our opinions about good and evil»","te":["voluntad","responsabilidad"]},{"i":"epicteto-033","a":"epicteto","t":"Es imposible empezar a aprender lo que uno cree que ya sabe.","o":"For it is impossible for a man to begin to learn that which he thinks that he knows.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we must adapt preconceptions to particular cases»","te":["educacion","conocimiento"]},{"i":"epicteto-034","a":"epicteto","t":"Todo hábito y toda capacidad se mantienen y crecen con las acciones que les corresponden.","o":"Every habit and faculty is maintained and increased by the corresponding actions","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we should struggle against appearances»","te":["habitos"]},{"i":"epicteto-035","a":"epicteto","t":"Si querés ser un buen lector, leé; si querés ser escritor, escribí.","o":"If you would be a good reader, read; if a writer, write.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we should struggle against appearances»","te":["habitos","educacion"]},{"i":"epicteto-036","a":"epicteto","t":"En general, si querés que algo se vuelva hábito, hacelo; si no querés, no lo hagas.","o":"Generally then if you would make anything a habit, do it; if you would not make it a habit, do not do it","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we should struggle against appearances»","te":["habitos","cambio"]},{"i":"epicteto-037","a":"epicteto","t":"El comienzo de la filosofía, para quien entra en ella como corresponde, es la conciencia de la propia debilidad e incapacidad en las cosas necesarias.","o":"The beginning of philosophy, to him at least who enters on it in the right way and by the door is a consciousness of his own weakness and inability about necessary things","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«What the beginning of philosophy is»","te":["autoconocimiento","conocimiento"]},{"i":"epicteto-038","a":"epicteto","t":"Es libre quien vive como quiere vivir, sin estar sometido a la coacción, al impedimento ni a la fuerza.","o":"He is free who lives as he wishes to live; who is neither subject to compulsion nor to hindrance, nor to force","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«About freedom»","te":["libertad"]},{"i":"epicteto-039","a":"epicteto","t":"Tengo que morir. ¿Tengo entonces que morir lamentándome? Me van a encadenar. ¿Tengo también que lamentarme?","o":"I must die. Must I then die lamenting? I must be put in chains. Must I then also lament?","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«Of the things which are in our power and not in our power»","te":["muerte","aceptacion","libertad"]},{"i":"epicteto-040","a":"epicteto","t":"Quien entiende qué es el bien sabe también amar.","o":"Whoever then understands what is good can also know how to love","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«On friendship»","te":["amor","amistad"]},{"i":"epicteto-041","a":"epicteto","t":"La soledad es la condición de una persona desamparada. Porque alguien esté solo no por eso está en soledad.","o":"Solitude is a certain condition of a helpless man. For because a man is alone, he is not for that reason also solitary","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«What solitude is, and what kind of person a solitary man is»","te":["soledad","vinculos"]},{"i":"epicteto-042","a":"epicteto","t":"Si sos alguien, caminá solo, hablá con vos mismo y no te escondas en el coro.","o":"Man, if you are anything, both walk alone and talk to yourself, and do not hide yourself in the chorus.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«Certain miscellaneous matters»","te":["soledad","autenticidad","identidad"]},{"i":"epicteto-043","a":"epicteto","t":"Examinate un poco por fin, mirá a tu alrededor, sacudite, para saber quién sos.","o":"Examine a little at last, look around, stir yourself up, that you may know who you are.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«Certain miscellaneous matters»","te":["autoconocimiento","identidad"]},{"i":"epicteto-044","a":"epicteto","t":"Quien trata con frecuencia con otros, para conversar, beber juntos o por la vida social, termina pareciéndose a ellos o haciéndolos parecidos a él.","o":"If a man has frequent intercourse with others either for talk, or drinking together, or generally for social purposes, he must either become like them, or change them to his own fashion.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«That we ought with caution to enter into familiar intercourse with men»","te":["vinculos","amistad"]},{"i":"epicteto-045","a":"epicteto","t":"Las cosas en sí son indiferentes; el uso que hacemos de ellas, no.","o":"Things themselves (materials) are indifferent; but the use of them is not indifferent.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How magnanimity is consistent with care»","te":["responsabilidad"]},{"i":"epicteto-046","a":"epicteto","t":"Lo exterior no depende de mí; la voluntad, sí.","o":"Externals are not in my power: will is in my power.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How magnanimity is consistent with care»","te":["libertad","voluntad","aceptacion"]},{"i":"epicteto-047","a":"epicteto","t":"Para cada persona, la causa de sus actos es su opinión.","o":"For to every man the cause of his acting is opinion.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«To a certain rhetorician who was going up to rome on a suit»","te":["conciencia","responsabilidad"]},{"i":"epicteto-048","a":"epicteto","t":"[Para alabar la Providencia hacen falta dos cosas:] la capacidad de ver lo que pertenece y sucede a todas las personas y cosas, y una disposición agradecida.","o":"the faculty of seeing what belongs and happens to all persons and things, and a grateful disposition","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«Of providence»","te":["gratitud","atencion"]},{"i":"epicteto-049","a":"epicteto","t":"Considerá quién sos.","o":"Consider who you are.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we may discover the duties of life from names»","te":["identidad","autoconocimiento"]},{"i":"epicteto-050","a":"epicteto","t":"Además, sos ciudadano del mundo y parte de él.","o":"Further, you are a citizen of the world, and a part of it","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we may discover the duties of life from names»","te":["sociedad","conexion"]},{"i":"epicteto-051","a":"epicteto","t":"No debemos retroceder cuando estamos en el combate más grande: hasta hay que recibir golpes.","o":"For we must not shrink when we are engaged in the greatest combat, but we must even take blows.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«From their purpose»","te":["resiliencia"]},{"i":"epicteto-052","a":"epicteto","t":"Creo que nadie tuvo una dificultad más provechosa que la tuya, si querés aprovecharla como un atleta a un rival joven.","o":"In my opinion no man has had a more profitable difficulty than you have had, if you choose to make use of it as an athlete would deal with a young antagonist.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we should struggle with circumstances»","te":["resiliencia","sufrimiento"]},{"i":"epicteto-053","a":"epicteto","t":"La filosofía no promete conseguirle a nadie nada exterior.","o":"Philosophy does not propose to secure for a man any external thing.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«What philosophy promises»","te":["sentido-de-vida","libertad"]},{"i":"epicteto-001","a":"epicteto","t":"De las cosas, unas dependen de nosotros y otras no.","o":"Of things some are in our power, and others are not.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 1","te":["libertad","aceptacion","responsabilidad"]},{"i":"epicteto-002","a":"epicteto","t":"Si amás una vasija de barro, decite que amás una vasija de barro: cuando se rompa, no te perturbará.","o":"If you love an earthen vessel, say it is an earthen vessel which you love; for when it has been broken you will not be disturbed.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 3","te":["perdida","aceptacion"]},{"i":"epicteto-003","a":"epicteto","t":"A los seres humanos no los perturban las cosas que suceden, sino las opiniones sobre las cosas.","o":"Men are disturbed not by the things which happen, but by the opinions about the things","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 5","te":["sufrimiento","conciencia","regulacion-emocional"]},{"i":"epicteto-004","a":"epicteto","t":"Lo terrible es la opinión de que la muerte es terrible.","o":"for the opinion about death that it is terrible, is the terrible thing.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 5","te":["muerte","miedo"]},{"i":"epicteto-005","a":"epicteto","t":"No pretendas que las cosas sucedan como querés: querelas como suceden, y tu vida fluirá en calma.","o":"Seek not that the things which happen should happen as you wish; but wish the things which happen to be as they are, and you will have a tranquil flow of life.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 8","te":["aceptacion","felicidad"]},{"i":"epicteto-006","a":"epicteto","t":"La enfermedad es un impedimento para el cuerpo, pero no para la voluntad, a menos que ella misma lo elija.","o":"Disease is an impediment to the body, but not to the will, unless the will itself chooses.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 9","te":["cuerpo","libertad","resiliencia"]},{"i":"epicteto-007","a":"epicteto","t":"Ante cada cosa que te suceda, acordate de volver a vos y preguntarte qué capacidad tenés para aprovecharla.","o":"On the occasion of every accident (event) that befalls you, remember to turn to yourself and inquire what power you have for turning it to use.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 10","te":["resiliencia","responsabilidad"]},{"i":"epicteto-008","a":"epicteto","t":"Nunca digas de algo “lo perdí”, sino “lo devolví”.","o":"Never say about anything, I have lost it, but say I have restored it.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 11","te":["perdida","duelo","aceptacion"]},{"i":"epicteto-009","a":"epicteto","t":"Si querés progresar, aceptá que te consideren tonto e ignorante en las cosas exteriores.","o":"If you would improve, submit to be considered without sense and foolish with respect to externals.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 13","te":["autenticidad","transformacion-personal"]},{"i":"epicteto-010","a":"epicteto","t":"Recordá que en la vida tenés que comportarte como en un banquete.","o":"Remember that in life you ought to behave as at a banquet.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 15","te":["deseo","aceptacion"]},{"i":"epicteto-011","a":"epicteto","t":"Recordá que sos un actor en una obra, tal como el autor quiera que sea.","o":"Remember that thou art an actor in a play, of such a kind as the teacher (author) may choose","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 17","te":["identidad","aceptacion"]},{"i":"epicteto-012","a":"epicteto","t":"Podés ser invencible si no entrás en ninguna contienda en la que vencer no dependa de vos.","o":"You can be invincible, if you enter into no contest in which it is not in your power to conquer.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 19","te":["libertad","resiliencia"]},{"i":"epicteto-013","a":"epicteto","t":"Recordá que no te ofende quien te insulta o te golpea, sino tu opinión de que eso es ofensivo.","o":"Remember that it is not he who reviles you or strikes you, who insults you, but it is your opinion about these things as being insulting.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 20","te":["ira","conciencia"]},{"i":"epicteto-014","a":"epicteto","t":"Cuando alguien te irrita, sabé que lo que te irritó es tu propia opinión.","o":"When then a man irritates you, you must know that it is your own opinion which has irritated you.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 20","te":["ira","regulacion-emocional"]},{"i":"epicteto-015","a":"epicteto","t":"Tené cada día ante los ojos la muerte, el exilio y todo lo que parece terrible, sobre todo la muerte: nunca pensarás nada mezquino ni desearás nada en exceso.","o":"Let death and exile and every other thing which appears dreadful be daily before your eyes; but most of all death: and you will never think of anything mean nor will you desire anything extravagantly.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 21","te":["muerte","deseo"]},{"i":"epicteto-016","a":"epicteto","t":"Si alguna vez te volcás hacia lo exterior para agradar a alguien, sabé que perdiste el rumbo de tu vida.","o":"If it should ever happen to you to be turned to externals in order to please some person, you must know that you have lost your purpose in life.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 23","te":["autenticidad","sentido-de-vida"]},{"i":"epicteto-017","a":"epicteto","t":"[Te indignaría que alguien entregara tu cuerpo a un desconocido;] pero que pongas tu mente en manos de cualquiera, de modo que si te insulta quede turbada, ¿no te avergüenza?","o":"but that you put your understanding in the power of any man whom you meet, so that if he should revile you, it is disturbed and troubled, are you not ashamed at this?","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 28","te":["libertad","autoestima"]},{"i":"epicteto-018","a":"epicteto","t":"Que el silencio sea la regla general, o que se diga solo lo necesario y en pocas palabras.","o":"And let silence be the general rule, or let only what is necessary be said, and in few words.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 33","te":["silencio","comunicacion"]},{"i":"epicteto-019","a":"epicteto","t":"[Ante la impresión de un placer,] que la cosa te espere, y concedete cierta demora.","o":"but let the thing wait for you, and allow yourself a certain delay on your own part.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 34","te":["deseo","regulacion-emocional"]},{"i":"epicteto-020","a":"epicteto","t":"Cuando decidiste que algo debe hacerse y lo estás haciendo, no evites que te vean, aunque muchos opinen mal de ello.","o":"When you have decided that a thing ought to be done, and are doing it, never avoid being seen doing it, though the many shall form an unfavorable opinion about it.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 35","te":["autenticidad","responsabilidad"]},{"i":"epicteto-021","a":"epicteto","t":"Que todo tu cuidado se dirija a la mente.","o":"let all your care be directed to the mind.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 41","te":["autoconocimiento"]},{"i":"epicteto-022","a":"epicteto","t":"Cuando alguien te trata mal o habla mal de vos, recordá que lo hace o lo dice porque cree que es lo que corresponde.","o":"When any person treats you ill or speaks ill of you, remember that he does this or says this because he thinks that it is his duty.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 42","te":["vinculos","compasion","ira"]},{"i":"epicteto-023","a":"epicteto","t":"Todo tiene dos asas: una por la que se lo puede llevar y otra por la que no.","o":"Everything has two handles, the one by which it may be borne, the other by which it may not.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 43","te":["aceptacion","vinculos"]},{"i":"epicteto-024","a":"epicteto","t":"Antes de conocer su razón, ¿cómo sabés si obra mal?","o":"For before you shall have determined the opinion how do you know whether he is acting wrong?","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 45","te":["vinculos","comunicacion"]},{"i":"epicteto-025","a":"epicteto","t":"En un banquete no digas cómo hay que comer: comé como se debe.","o":"at a banquet do not say how a man ought to eat, but eat as you ought to eat.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 46","te":["autenticidad","habitos"]},{"i":"epicteto-026","a":"epicteto","t":"Lo propio del filósofo es esto: espera de sí mismo todo beneficio y todo daño.","o":"The condition and characteristic of a philosopher is this: he expects all advantage and all harm from himself.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 48","te":["responsabilidad","libertad"]},{"i":"epicteto-027","a":"epicteto","t":"Y lo que digan de vos, no le prestes atención: no es asunto tuyo.","o":"And whatever any man shall say about you, do not attend to it; for this is no affair of yours.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 50","te":["autoestima","libertad"]},{"i":"epicteto-028","a":"epicteto","t":"Si querés que tus hijos, tu pareja y tus amigos vivan para siempre, sos un ingenuo.","o":"If you would have your children and your wife and your friends to live for ever, you are silly","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 14","te":["muerte","aceptacion","vinculos"]},{"i":"friedrich-nietzsche-026","a":"friedrich-nietzsche","t":"Hay que tener todavía caos dentro de sí para poder dar a luz una estrella danzante.","o":"man muss noch Chaos in sich haben, um einen tanzenden Stern gebären zu können","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["creatividad","transformacion-personal"]},{"i":"friedrich-nietzsche-027","a":"friedrich-nietzsche","t":"El ser humano es una cuerda tendida entre el animal y el superhombre.","o":"Der Mensch ist ein Seil, geknüpft zwischen Thier und Übermensch","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["existencia","transformacion-personal"]},{"i":"friedrich-nietzsche-028","a":"friedrich-nietzsche","t":"Lo grande del ser humano es que es un puente y no una meta.","o":"Was gross ist am Menschen, das ist, dass er eine Brücke und kein Zweck ist","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["transformacion-personal","cambio"]},{"i":"friedrich-nietzsche-029","a":"friedrich-nietzsche","t":"Solo creería en un dios que supiera bailar.","o":"Ich würde nur an einen Gott glauben, der zu tanzen verstünde.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["trascendencia","alegria"]},{"i":"friedrich-nietzsche-030","a":"friedrich-nietzsche","t":"Siempre hay algo de locura en el amor. Pero siempre hay también algo de razón en la locura.","o":"Es ist immer etwas Wahnsinn in der Liebe. Es ist aber immer auch etwas Vernunft im Wahnsinn.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["amor","deseo"]},{"i":"friedrich-nietzsche-031","a":"friedrich-nietzsche","t":"Detrás de tus pensamientos y sentimientos, hermano, hay un soberano poderoso, un sabio desconocido: se llama “sí mismo”. Habita en tu cuerpo; es tu cuerpo.","o":"Hinter deinen Gedanken und Gefühlen, mein Bruder, steht ein mächtiger Gebieter, ein unbekannter Weiser-der heisst Selbst. In deinem Leibe wohnt er, dein Leib ist er.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["cuerpo","inconsciente","identidad"]},{"i":"friedrich-nietzsche-032","a":"friedrich-nietzsche","t":"Hay más razón en tu cuerpo que en tu mejor sabiduría.","o":"Es ist mehr Vernunft in deinem Leibe, als in deiner besten Weisheit.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["cuerpo","conocimiento"]},{"i":"friedrich-nietzsche-033","a":"friedrich-nietzsche","t":"También tu pequeña razón es una herramienta de tu cuerpo.","o":"Werkzeug deines Leibes ist auch deine kleine Vernunft","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["cuerpo","conciencia"]},{"i":"friedrich-nietzsche-034","a":"friedrich-nietzsche","t":"Tenés que querer quemarte en tu propia llama: ¿cómo querrías renovarte si antes no te hiciste ceniza?","o":"Verbrennen musst du dich wollen in deiner eignen Flamme: wie wolltest du neu werden, wenn du nicht erst Asche geworden bist!","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["transformacion-personal","cambio"]},{"i":"friedrich-nietzsche-035","a":"friedrich-nietzsche","t":"Solitario, recorrés el camino hacia vos mismo.","o":"Einsamer, du gehst den Weg zu dir selber!","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["soledad","autoconocimiento"]},{"i":"friedrich-nietzsche-036","a":"friedrich-nietzsche","t":"Pero el peor enemigo que podés encontrar siempre serás vos mismo.","o":"Aber der schlimmste Feind, dem du begegnen kannst, wirst du immer dir selber sein","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["autoconocimiento","sufrimiento"]},{"i":"friedrich-nietzsche-037","a":"friedrich-nietzsche","t":"En verdad, el ser humano es un río sucio. Hay que ser un mar para poder recibir un río sucio sin volverse impuro.","o":"Wahrlich, ein schmutziger Strom ist der Mensch. Man muss schon ein Meer sein, um einen schmutzigen Strom aufnehmen zu können, ohne unrein zu werden.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["aceptacion","existencia"]},{"i":"friedrich-nietzsche-038","a":"friedrich-nietzsche","t":"El valor es el mejor matador, el valor que ataca: hasta a la muerte mata.","o":"Muth aber ist der beste Todtschläger, Muth, der angreift: der schlägt noch den Tod todt","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Dritter Theil","te":["miedo","muerte","resiliencia"]},{"i":"friedrich-nietzsche-039","a":"friedrich-nietzsche","t":"¿Eso era la vida? ¡Bien! ¡Otra vez!","o":"War _das_ das Leben? Wohlan! Noch Ein Mal!","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Dritter Theil","te":["sentido-de-vida","aceptacion"]},{"i":"friedrich-nietzsche-040","a":"friedrich-nietzsche","t":"Se le paga mal a un maestro si se sigue siendo siempre solo su alumno.","o":"Man vergilt einem Lehrer schlecht, wenn man immer nur der Schüler bleibt.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["educacion","autenticidad"]},{"i":"friedrich-nietzsche-041","a":"friedrich-nietzsche","t":"El ser humano es algo que debe ser superado.","o":"Der Mensch ist Etwas, das überwunden werden soll.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["transformacion-personal"]},{"i":"friedrich-nietzsche-042","a":"friedrich-nietzsche","t":"Permanezcan fieles a la tierra.","o":"bleibt der Erde treu","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["naturaleza","cuerpo"]},{"i":"friedrich-nietzsche-043","a":"friedrich-nietzsche","t":"Toda la vida es una disputa sobre gustos y sabores.","o":"alles Leben ist Streit um Geschmack und Schmecken","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Zweiter Theil","te":["existencia","deseo"]},{"i":"friedrich-nietzsche-044","a":"friedrich-nietzsche","t":"De todo lo escrito, solo amo lo que alguien escribe con su sangre.","o":"Von allem Geschriebenen liebe ich nur Das, was Einer mit seinem Blute schreibt.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["autenticidad","creatividad"]},{"i":"friedrich-nietzsche-011","a":"friedrich-nietzsche","t":"Quien lucha con monstruos debe cuidar de no convertirse en monstruo. Y si mirás largo tiempo a un abismo, el abismo también mira dentro de vos.","o":"Wer mit Ungeheuern kämpft, mag zusehn, dass er nicht dabei zum Ungeheuer wird. Und wenn du lange in einen Abgrund blickst, blickt der Abgrund auch in dich hinein.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 146","te":["identidad","inconsciente"]},{"i":"friedrich-nietzsche-012","a":"friedrich-nietzsche","t":"“Esto lo hice yo”, dice mi memoria. “Esto no puedo haberlo hecho”, dice mi orgullo, y se mantiene inflexible. Al final, cede la memoria.","o":"\"Das habe ich gethan\" sagt mein Gedächtniss. Das kann ich nicht gethan haben - sagt mein Stolz und bleibt unerbittlich. Endlich - giebt das Gedächtniss nach.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 68","te":["memoria","autoestima","inconsciente"]},{"i":"friedrich-nietzsche-013","a":"friedrich-nietzsche","t":"Lo que se hace por amor sucede siempre más allá del bien y del mal.","o":"Was aus Liebe gethan wird, geschieht immer jenseits von Gut und Böse.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 153","te":["amor"]},{"i":"friedrich-nietzsche-014","a":"friedrich-nietzsche","t":"La locura es algo raro en los individuos; pero en los grupos, los partidos, los pueblos y las épocas, es la regla.","o":"Der Irrsinn ist bei Einzelnen etwas Seltenes, - aber bei Gruppen, Parteien, Völkern, Zeiten die Regel.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 156","te":["sociedad","salud-mental"]},{"i":"friedrich-nietzsche-015","a":"friedrich-nietzsche","t":"Quien se desprecia a sí mismo se respeta todavía, en eso, como despreciador.","o":"Wer sich selbst verachtet, achtet sich doch immer noch dabei als Verächter.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 78","te":["autoestima","identidad"]},{"i":"friedrich-nietzsche-016","a":"friedrich-nietzsche","t":"Al final, uno ama su deseo y no lo deseado.","o":"Man liebt zuletzt seine Begierde, und nicht das Begehrte.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 175","te":["deseo","amor"]},{"i":"friedrich-nietzsche-017","a":"friedrich-nietzsche","t":"Todo lo profundo ama la máscara.","o":"Alles, was tief ist, liebt die Maske","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 40","te":["identidad","autenticidad"]},{"i":"friedrich-nietzsche-018","a":"friedrich-nietzsche","t":"No me conmovió que me mintieras, sino que ya no pueda creerte.","o":"Nicht dass du mich belogst, sondern dass ich dir nicht mehr glaube, hat mich erschüttert.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 183","te":["vinculos","verdad","perdida"]},{"i":"friedrich-nietzsche-019","a":"friedrich-nietzsche","t":"No hay fenómenos morales, sino solo una interpretación moral de los fenómenos.","o":"Es giebt gar keine moralischen Phänomene, sondern nur eine moralische Ausdeutung von Phänomenen","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 108","te":["verdad","cultura"]},{"i":"friedrich-nietzsche-020","a":"friedrich-nietzsche","t":"Uno ya no ama lo suficiente su conocimiento en cuanto lo comunica.","o":"Man liebt seine Erkenntniss nicht genug mehr, sobald man sie mittheilt.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 160","te":["conocimiento","comunicacion"]},{"i":"friedrich-nietzsche-021","a":"friedrich-nietzsche","t":"Un pensamiento viene cuando “él” quiere, y no cuando “yo” quiero.","o":"ein Gedanke kommt, wenn \"er\" will, und nicht wenn \"ich\" will","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 17","te":["inconsciente","conciencia"]},{"i":"friedrich-nietzsche-022","a":"friedrich-nietzsche","t":"Madurez del hombre: haber reencontrado la seriedad que se tenía de niño al jugar.","o":"Reife des Mannes: das heisst den Ernst wiedergefunden haben, den man als Kind hatte, beim Spiel.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 94","te":["infancia","desarrollo-humano"]},{"i":"friedrich-nietzsche-023","a":"friedrich-nietzsche","t":"Que un juicio sea falso no es todavía, para nosotros, una objeción contra ese juicio.","o":"Die Falschheit eines Urtheils ist uns noch kein Einwand gegen ein Urtheil","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 4","te":["verdad","conocimiento"]},{"i":"friedrich-nietzsche-024","a":"friedrich-nietzsche","t":"El amor saca a la luz las cualidades elevadas y ocultas de quien ama.","o":"Die Liebe bringt die hohen und verborgenen Eigenschaften eines Liebenden an's Licht","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 163","te":["amor","identidad"]},{"i":"friedrich-nietzsche-025","a":"friedrich-nietzsche","t":"[¿Un gran hombre?] Siempre veo solo al actor de su propio ideal.","o":"Ich sehe immer nur den Schauspieler seines eignen Ideals","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 97","te":["identidad","autenticidad"]},{"i":"friedrich-nietzsche-001","a":"friedrich-nietzsche","t":"Lo que no me mata me hace más fuerte.","o":"Was mich nicht umbringt, macht mich stärker.","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 8","te":["resiliencia","sufrimiento"]},{"i":"friedrich-nietzsche-002","a":"friedrich-nietzsche","t":"Si se tiene un “por qué” para vivir, se soporta casi cualquier “cómo”.","o":"Hat man sein warum? des Lebens, so verträgt man sich fast mit jedem wie?","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 12","te":["sentido-de-vida","resiliencia"]},{"i":"friedrich-nietzsche-003","a":"friedrich-nietzsche","t":"Sin música, la vida sería un error.","o":"Ohne Musik wäre das Leben ein Irrthum.","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 33","te":["alegria","cultura"]},{"i":"friedrich-nietzsche-004","a":"friedrich-nietzsche","t":"El ocio es el comienzo de toda psicología.","o":"Müssiggang ist aller Psychologie Anfang.","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 1","te":["autoconocimiento","humor"]},{"i":"friedrich-nietzsche-005","a":"friedrich-nietzsche","t":"Hasta el más valiente de nosotros rara vez tiene el valor de lo que en verdad sabe.","o":"Auch der Muthigste von uns hat nur selten den Muth zu dem, was er eigentlich weiss","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 2","te":["miedo","verdad"]},{"i":"friedrich-nietzsche-006","a":"friedrich-nietzsche","t":"La sabiduría también le pone límites al conocimiento.","o":"Die Weisheit zieht auch der Erkenntniss Grenzen.","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 5","te":["conocimiento"]},{"i":"friedrich-nietzsche-007","a":"friedrich-nietzsche","t":"Desconfío de todos los sistemáticos y los evito. La voluntad de sistema es una falta de honestidad.","o":"Ich misstraue allen Systematikern und gehe ihnen aus dem Weg. Der Wille zum System ist ein Mangel an Rechtschaffenheit.","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 26","te":["verdad","autenticidad"]},{"i":"friedrich-nietzsche-008","a":"friedrich-nietzsche","t":"Solo valen los pensamientos que nacen caminando.","o":"Nur die ergangenen Gedanken haben Werth.","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 34","te":["cuerpo","creatividad"]},{"i":"friedrich-nietzsche-009","a":"friedrich-nietzsche","t":"¿Es el ser humano solo un error de Dios? ¿O Dios solo un error del ser humano?","o":"ist der Mensch nur ein Fehlgriff Gottes? Oder Gott nur ein Fehlgriff des Menschen?","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 7","te":["trascendencia","existencia"]},{"i":"friedrich-nietzsche-010","a":"friedrich-nietzsche","t":"El gusano pisado se enrosca. Así es prudente.","o":"Der getretene Wurm krümmt sich. So ist es klug.","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 31","te":["poder","humor"]},{"i":"friedrich-nietzsche-045","a":"friedrich-nietzsche","t":"Mi fórmula para la grandeza del ser humano es amor fati: no querer que nada sea distinto, ni hacia adelante, ni hacia atrás, ni por toda la eternidad.","o":"Meine Formel für die Grösse am Menschen ist amor fati: dass man Nichts anders haben will, vorwärts nicht, rückwärts nicht, in alle Ewigkeit nicht.","l":"de","ob":"Ecce homo","an":"1888 (publ. 1908)","u":"«Warum ich so klug bin», § 10","te":["aceptacion","sentido-de-vida"]},{"i":"friedrich-nietzsche-046","a":"friedrich-nietzsche","t":"No darle crédito a ningún pensamiento que no haya nacido al aire libre.","o":"keinem Gedanken Glauben schenken, der nicht im Freien geboren ist","l":"de","ob":"Ecce homo","an":"1888 (publ. 1908)","u":"«Warum ich so klug bin»","te":["cuerpo","naturaleza","creatividad"]},{"i":"friedrich-nietzsche-047","a":"friedrich-nietzsche","t":"Llegar a ser lo que uno es supone no sospechar ni remotamente lo que uno es.","o":"Dass man wird, was man ist, setzt voraus, dass man nicht im Entferntesten ahnt, was man ist.","l":"de","ob":"Ecce homo","an":"1888 (publ. 1908)","u":"«Warum ich so klug bin», § 9","te":["identidad","desarrollo-humano","autoconocimiento"]},{"i":"friedrich-nietzsche-048","a":"friedrich-nietzsche","t":"No soy un hombre, soy dinamita.","o":"Ich bin kein Mensch, ich bin Dynamit.","l":"de","ob":"Ecce homo","an":"1888 (publ. 1908)","u":"«Warum ich ein Schicksal bin», § 1","te":["identidad"]},{"i":"friedrich-nietzsche-049","a":"friedrich-nietzsche","t":"Las convicciones son enemigas de la verdad más peligrosas que las mentiras.","o":"Ueberzeugungen sind gefährlichere Feinde der Wahrheit, als Lügen.","l":"de","ob":"Humano, demasiado humano","an":"1878","u":"§ 483","te":["verdad"]},{"i":"friedrich-nietzsche-050","a":"friedrich-nietzsche","t":"[La esperanza] es, en verdad, el peor de los males, porque prolonga el tormento de los seres humanos.","o":"sie ist in Wahrheit das übelste der Uebel, weil sie die Qual der Menschen verlängert","l":"de","ob":"Humano, demasiado humano","an":"1878","u":"§ 71","te":["esperanza","sufrimiento"]},{"i":"friedrich-nietzsche-051","a":"friedrich-nietzsche","t":"Lo que hace al amigo es compartir la alegría, no compartir el sufrimiento.","o":"Mitfreude, nicht Mitleiden, macht den Freund.","l":"de","ob":"Humano, demasiado humano","an":"1878","u":"§ 499","te":["amistad","alegria"]},{"i":"friedrich-nietzsche-052","a":"friedrich-nietzsche","t":"Quien haya llegado aunque sea un poco a la libertad de la razón no puede sentirse en la tierra sino como un caminante.","o":"Wer nur einigermaassen zur Freiheit der Vernunft gekommen ist, kann sich auf Erden nicht anders fühlen, denn als Wanderer","l":"de","ob":"Humano, demasiado humano","an":"1878","u":"§ 638","te":["libertad","existencia"]},{"i":"buda-001","a":"buda","t":"Todo lo que somos es el resultado de lo que hemos pensado: está fundado en nuestros pensamientos, está hecho de nuestros pensamientos.","o":"All that we are is the result of what we have thought: it is founded on our thoughts, it is made up of our thoughts.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 1","te":["conciencia","identidad"]},{"i":"buda-002","a":"buda","t":"El odio nunca cesa con el odio: el odio cesa con el amor. Esta es una ley antigua.","o":"For hatred does not cease by hatred at any time: hatred ceases by love, this is an old rule.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 1, verso 5","te":["ira","amor","compasion"]},{"i":"buda-003","a":"buda","t":"El mundo no sabe que todos hemos de terminar aquí; pero quienes lo saben, dejan enseguida de pelear.","o":"The world does not know that we must all come to an end here;--but those who know it, their quarrels cease at once.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 1, verso 6","te":["muerte","vinculos"]},{"i":"buda-004","a":"buda","t":"Quienes imaginan verdad en lo falso y ven falsedad en lo verdadero nunca llegan a la verdad: siguen deseos vanos.","o":"They who imagine truth in untruth, and see untruth in truth, never arrive at truth, but follow vain desires.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 1, verso 11","te":["verdad","deseo"]},{"i":"buda-005","a":"buda","t":"Así como la lluvia no atraviesa una casa bien techada, la pasión no atraviesa una mente que reflexiona.","o":"As rain does not break through a well-thatched house, passion will not break through a well-reflecting mind.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 1, verso 14","te":["regulacion-emocional","conciencia"]},{"i":"buda-006","a":"buda","t":"Despertándose, con empeño, con mesura y dominio de sí, el sabio puede hacerse una isla que ninguna inundación logre cubrir.","o":"By rousing himself, by earnestness, by restraint and control, the wise man may make for himself an island which no flood can overwhelm.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 2, verso 25","te":["resiliencia","autoconocimiento"]},{"i":"buda-007","a":"buda","t":"Atento entre los distraídos, despierto entre los dormidos, el sabio avanza como un caballo de carrera que deja atrás al rocín.","o":"Earnest among the thoughtless, awake among the sleepers, the wise man advances like a racer, leaving behind the hack.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 2, verso 29","te":["atencion","presencia"]},{"i":"buda-008","a":"buda","t":"Es bueno domar la mente, difícil de sujetar y voluble, que corre adonde se le antoja: una mente domada trae felicidad.","o":"It is good to tame the mind, which is difficult to hold in and flighty, rushing wherever it listeth; a tamed mind brings happiness.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 3, verso 35","te":["atencion","felicidad","regulacion-emocional"]},{"i":"buda-009","a":"buda","t":"Que el sabio cuide sus pensamientos, porque son difíciles de percibir, muy astutos, y corren adonde quieren: los pensamientos bien cuidados traen felicidad.","o":"Let the wise man guard his thoughts, for they are difficult to perceive, very artful, and they rush wherever they list: thoughts well guarded bring happiness.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 3, verso 36","te":["conciencia","atencion"]},{"i":"buda-010","a":"buda","t":"Lo que un enemigo pueda hacerle a otro enemigo, más daño nos hará una mente mal dirigida.","o":"Whatever a hater may do to a hater, or an enemy to an enemy, a wrongly-directed mind will do us greater mischief.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 3, verso 42","te":["conciencia","sufrimiento"]},{"i":"buda-011","a":"buda","t":"Ni una madre, ni un padre, ni ningún otro pariente harán tanto por nosotros como una mente bien dirigida.","o":"Not a mother, not a father will do so much, nor any other relative; a well-directed mind will do us greater service.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 3, verso 43","te":["conciencia","familia"]},{"i":"buda-012","a":"buda","t":"No las faltas de los otros, ni lo que hicieron o dejaron de hacer: el sabio debe fijarse en sus propios errores y descuidos.","o":"Not the perversities of others, not their sins of commission or omission, but his own misdeeds and negligences should a sage take notice of.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 4, verso 50","te":["autoconocimiento","responsabilidad"]},{"i":"buda-013","a":"buda","t":"Como una flor hermosa, llena de color pero sin perfume, son las palabras bellas y estériles de quien no actúa en consecuencia.","o":"Like a beautiful flower, full of colour, but without scent, are the fine but fruitless words of him who does not act accordingly.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 4, verso 51","te":["autenticidad","comunicacion"]},{"i":"buda-014","a":"buda","t":"Si un caminante no encuentra a alguien mejor o igual que él, que siga con firmeza su camino solitario: no hay compañía posible con un necio.","o":"If a traveller does not meet with one who is his better, or his equal, let him firmly keep to his solitary journey; there is no companionship with a fool.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 5, verso 61","te":["soledad","vinculos"]},{"i":"buda-015","a":"buda","t":"El necio que conoce su necedad es, al menos en eso, sabio. Pero el necio que se cree sabio es un necio de verdad.","o":"The fool who knows his foolishness, is wise at least so far. But a fool who thinks himself wise, he is called a fool indeed.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 5, verso 63","te":["autoconocimiento","conocimiento"]},{"i":"buda-016","a":"buda","t":"Como una roca firme no se mueve con el viento, los sabios no vacilan entre la crítica y el elogio.","o":"As a solid rock is not shaken by the wind, wise people falter not amidst blame and praise.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 6, verso 81","te":["resiliencia","autoestima"]},{"i":"buda-017","a":"buda","t":"Los sabios, después de escuchar la enseñanza, se vuelven serenos como un lago profundo, liso y quieto.","o":"Wise people, after they have listened to the laws, become serene, like a deep, smooth, and still lake.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 6, verso 82","te":["silencio","presencia"]},{"i":"buda-018","a":"buda","t":"Si uno vence en batalla mil veces a mil hombres, y otro se vence a sí mismo, este es el mayor de los vencedores.","o":"If one man conquer in battle a thousand times thousand men, and if another conquer himself, he is the greatest of conquerors.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 8, verso 103","te":["autoconocimiento","regulacion-emocional"]},{"i":"buda-019","a":"buda","t":"Si alguien obra mal, que no lo repita ni se complazca en ello: el dolor es el fruto del mal.","o":"If a man commits a sin, let him not do it again; let him not delight in sin: pain is the outcome of evil.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 9, verso 117","te":["responsabilidad","habitos"]},{"i":"buda-020","a":"buda","t":"Si alguien obra bien, que lo repita y se alegre en ello: la felicidad es el fruto del bien.","o":"If a man does what is good, let him do it again; let him delight in it: happiness is the outcome of good.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 9, verso 118","te":["habitos","felicidad"]},{"i":"buda-021","a":"buda","t":"Gota a gota se llena un cántaro.","o":"Even by the falling of water-drops a water-pot is filled","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 9, verso 121","te":["habitos","cambio"]},{"i":"buda-022","a":"buda","t":"Quien aprendió poco envejece como un buey: crece su carne, pero no su conocimiento.","o":"A man who has learnt little, grows old like an ox; his flesh grows, but his knowledge does not grow.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 11, verso 152","te":["educacion","desarrollo-humano"]},{"i":"buda-023","a":"buda","t":"Que cada uno se encamine primero hacia lo correcto y después enseñe a otros: así el sabio no sufrirá.","o":"Let each man direct himself first to what is proper, then let him teach others; thus a wise man will not suffer.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 12, verso 158","te":["autenticidad","educacion"]},{"i":"buda-024","a":"buda","t":"Uno mismo es dueño de sí: ¿quién más podría serlo? Con uno mismo bien dominado, se encuentra un señor como pocos encuentran.","o":"Self is the lord of self, who else could be the lord? With self well subdued, a man finds a lord such as few can find.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 12, verso 160","te":["autoconocimiento","libertad"]},{"i":"buda-025","a":"buda","t":"Lo malo y lo que nos daña es fácil de hacer; lo beneficioso y bueno es muy difícil.","o":"Bad deeds, and deeds hurtful to ourselves, are easy to do; what is beneficial and good, that is very difficult to do.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 12, verso 163","te":["habitos","voluntad"]},{"i":"buda-026","a":"buda","t":"Por uno mismo se hace el mal, por uno mismo se sufre; por uno mismo se deja de hacerlo, por uno mismo uno se purifica.","o":"By oneself the evil is done, by oneself one suffers; by oneself evil is left undone, by oneself one is purified.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 12, verso 165","te":["responsabilidad","transformacion-personal"]},{"i":"buda-027","a":"buda","t":"Mirá el mundo como una burbuja, miralo como un espejismo.","o":"Look upon the world as a bubble, look upon it as a mirage","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 13, verso 170","te":["existencia","cambio"]},{"i":"buda-028","a":"buda","t":"No hacer ningún mal, hacer el bien y purificar la propia mente: esa es la enseñanza de todos los Despiertos.","o":"Not to commit any sin, to do good, and to purify one's mind, that is the teaching of (all) the Awakened.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 14, verso 183","te":["trascendencia","conciencia"]},{"i":"buda-029","a":"buda","t":"No hay manera de saciar los deseos, ni siquiera con una lluvia de monedas de oro.","o":"There is no satisfying lusts, even by a shower of gold pieces","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 14, verso 186","te":["deseo","felicidad"]},{"i":"buda-030","a":"buda","t":"La victoria engendra odio, porque el vencido es desdichado. Quien renunció a la victoria y a la derrota, ese, el contento, es feliz.","o":"Victory breeds hatred, for the conquered is unhappy. He who has given up both victory and defeat, he, the contented, is happy.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 15, verso 201","te":["felicidad","ira","vinculos"]},{"i":"buda-031","a":"buda","t":"La salud es el mayor de los dones; el contento, la mejor riqueza; la confianza, el mejor de los vínculos; el nirvana, la felicidad suprema.","o":"Health is the greatest of gifts, contentedness the best riches; trust is the best of relationships, Nirvana the highest happiness.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 15, verso 204","te":["felicidad","vinculos","cuerpo"]},{"i":"buda-032","a":"buda","t":"Quien probó la dulzura de la soledad y la calma queda libre del miedo y del mal.","o":"He who has tasted the sweetness of solitude and tranquillity, is free from fear and free from sin","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 15, verso 205","te":["soledad","silencio","miedo"]},{"i":"buda-033","a":"buda","t":"Del apego nace la pena, del apego nace el miedo; quien está libre del apego no conoce la pena ni el miedo.","o":"From love comes grief, from love comes fear; he who is free from love knows neither grief nor fear.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 16, verso 215","te":["amor","duelo","miedo"]},{"i":"buda-034","a":"buda","t":"A quien frena la ira que surge como a un carro desbocado, a ese llamo verdadero conductor; los demás solo sostienen las riendas.","o":"He who holds back rising anger like a rolling chariot, him I call a real driver; other people are but holding the reins.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 17, verso 222","te":["ira","regulacion-emocional"]},{"i":"buda-035","a":"buda","t":"Que se venza la ira con amor, el mal con el bien, la avaricia con generosidad y la mentira con la verdad.","o":"Let a man overcome anger by love, let him overcome evil by good; let him overcome the greedy by liberality, the liar by truth!","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 17, verso 223","te":["ira","compasion","verdad"]},{"i":"buda-036","a":"buda","t":"Decí la verdad, no cedas a la ira; da, aunque te pidan poco.","o":"Speak the truth, do not yield to anger; give, if thou art asked for little","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 17, verso 224","te":["verdad","ira"]},{"i":"buda-037","a":"buda","t":"No hubo, no habrá ni hay ahora nadie que sea siempre criticado, ni nadie que sea siempre elogiado.","o":"There never was, there never will be, nor is there now, a man who is always blamed, or a man who is always praised.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 17, verso 228","te":["autoestima","aceptacion"]},{"i":"buda-038","a":"buda","t":"Hacete una isla, trabajá con empeño, sé sabio.","o":"Make thyself an island, work hard, be wise!","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 18, verso 236","te":["resiliencia","autoconocimiento"]},{"i":"buda-039","a":"buda","t":"La falta ajena se ve con facilidad; la propia, con dificultad.","o":"The fault of others is easily perceived, but that of oneself is difficult to perceive","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 18, verso 252","te":["autoconocimiento","vinculos"]},{"i":"buda-040","a":"buda","t":"Si alguien vive pendiente de las faltas de los demás y siempre dispuesto a ofenderse, sus propias pasiones crecerán.","o":"If a man looks after the faults of others, and is always inclined to be offended, his own passions will grow","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 18, verso 253","te":["ira","autoconocimiento"]},{"i":"buda-041","a":"buda","t":"Nadie es sabio por hablar mucho; sabio es quien es paciente y está libre de odio y de miedo.","o":"A man is not learned because he talks much; he who is patient, free from hatred and fear, he is called learned.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 19, verso 258","te":["conocimiento","miedo"]},{"i":"buda-042","a":"buda","t":"Vos mismo tenés que hacer el esfuerzo. Los Budas solo enseñan el camino.","o":"You yourself must make an effort. The Tathagatas (Buddhas) are only preachers.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 20, verso 276","te":["responsabilidad","transformacion-personal"]},{"i":"buda-043","a":"buda","t":"“Todo lo creado perece”: quien sabe y ve esto se vuelve sereno ante el dolor.","o":"'All created things perish,' he who knows and sees this becomes passive in pain","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 20, verso 277","te":["cambio","aceptacion","sufrimiento"]},{"i":"buda-044","a":"buda","t":"Con dedicación se gana el conocimiento; sin ella, se pierde.","o":"Through zeal knowledge is gotten, through lack of zeal knowledge is lost","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 20, verso 282","te":["educacion","habitos"]},{"i":"buda-045","a":"buda","t":"Si algo debe hacerse, que se haga, y con decisión.","o":"If anything is to be done, let a man do it, let him attack it vigorously!","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 22, verso 313","te":["voluntad","responsabilidad"]},{"i":"buda-046","a":"buda","t":"Esta mente mía andaba antes errante por donde quería, como se le antojaba, como le placía.","o":"This mind of mine went formerly wandering about as it liked, as it listed, as it pleased","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 23, verso 326","te":["atencion","conciencia"]},{"i":"buda-047","a":"buda","t":"No seas descuidado, vigilá tus pensamientos. Salí del mal camino como un elefante hundido en el barro.","o":"Be not thoughtless, watch your thoughts! Draw yourself out of the evil way, like an elephant sunk in mud.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 23, verso 327","te":["atencion","cambio"]},{"i":"buda-048","a":"buda","t":"Soltá lo que está adelante, soltá lo que está atrás, soltá lo que está en el medio.","o":"Give up what is before, give up what is behind, give up what is in the middle","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 24, verso 348","te":["aceptacion","presencia"]},{"i":"buda-049","a":"buda","t":"Sin conocimiento no hay meditación; sin meditación no hay conocimiento.","o":"Without knowledge there is no meditation, without meditation there is no knowledge","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 25, verso 372","te":["conocimiento","silencio"]},{"i":"buda-050","a":"buda","t":"Despertate por vos mismo, examinate por vos mismo: así, protegido por vos mismo y atento, vivirás feliz.","o":"Rouse thyself by thyself, examine thyself by thyself, thus self-protected and attentive wilt thou live happily","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 25, verso 379","te":["autoconocimiento","atencion","felicidad"]},{"i":"buda-051","a":"buda","t":"Que nadie menosprecie el bien diciéndose: “No llegará a mí”.","o":"Let no man think lightly of good, saying in his heart, It will not come nigh unto me.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 9, verso 122","te":["esperanza","habitos"]},{"i":"buda-052","a":"buda","t":"Como un pez sacado del agua y arrojado a tierra seca, nuestro pensamiento tiembla por entero.","o":"As a fish taken from his watery home and thrown on dry ground, our thought trembles all over","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 3, verso 34","te":["angustia","conciencia"]},{"i":"lao-tse-001","a":"lao-tse","t":"El Tao que puede recorrerse no es el Tao permanente e inmutable. El nombre que puede nombrarse no es el nombre permanente e inmutable.","o":"The Tao that can be trodden is not the enduring and unchanging Tao. The name that can be named is not the enduring and unchanging name.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 1","te":["trascendencia","conocimiento"]},{"i":"lao-tse-002","a":"lao-tse","t":"Todos en el mundo conocen la belleza de lo bello, y al hacerlo ya tienen la idea de lo feo.","o":"All in the world know the beauty of the beautiful, and in doing this they have (the idea of) what ugliness is","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 2","te":["conocimiento","existencia"]},{"i":"lao-tse-003","a":"lao-tse","t":"Deberíamos limar nuestras aristas y desenredar las complicaciones de las cosas.","o":"We should blunt our sharp points, and unravel the complications of things","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 4","te":["aceptacion","vinculos"]},{"i":"lao-tse-004","a":"lao-tse","t":"Por eso el sabio se pone en último lugar, y sin embargo se encuentra en el primero.","o":"Therefore the sage puts his own person last, and yet it is found in the foremost place","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 7","te":["poder","autenticidad"]},{"i":"lao-tse-005","a":"lao-tse","t":"La excelencia más alta es como la del agua.","o":"The highest excellence is like (that of) water.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 8","te":["naturaleza","aceptacion"]},{"i":"lao-tse-006","a":"lao-tse","t":"La excelencia del agua está en que beneficia a todas las cosas y ocupa, sin disputar, el lugar bajo que todos desprecian.","o":"The excellence of water appears in its benefiting all things, and in its occupying, without striving (to the contrary), the low place which all men dislike.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 8","te":["naturaleza","compasion"]},{"i":"lao-tse-007","a":"lao-tse","t":"La excelencia de la mente está en su quietud profunda.","o":"that of the mind is in abysmal stillness","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 8","te":["silencio","conciencia"]},{"i":"lao-tse-008","a":"lao-tse","t":"Es mejor dejar una vasija sin llenar que intentar llevarla cuando está colmada.","o":"It is better to leave a vessel unfilled, than to attempt to carry it when it is full.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 9","te":["deseo","aceptacion"]},{"i":"lao-tse-009","a":"lao-tse","t":"Cuando la obra está hecha y el nombre empieza a destacarse, retirarse a la sombra es el camino del cielo.","o":"When the work is done, and one's name is becoming distinguished, to withdraw into obscurity is the way of Heaven.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 9","te":["trabajo","poder"]},{"i":"lao-tse-010","a":"lao-tse","t":"Los treinta rayos se unen en un solo cubo; pero del espacio vacío depende la utilidad de la rueda.","o":"The thirty spokes unite in the one nave; but it is on the empty space (for the axle), that the use of the wheel depends.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 10","te":["silencio","existencia"]},{"i":"lao-tse-011","a":"lao-tse","t":"Cuando las plantas despliegan su crecimiento exuberante, vemos a cada una volver a su raíz.","o":"When things (in the vegetable world) have displayed their luxuriant growth, we see each of them return to its root.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 16","te":["naturaleza","cambio"]},{"i":"lao-tse-012","a":"lao-tse","t":"Este volver a la raíz es lo que llamamos quietud.","o":"This returning to their root is what we call the state of stillness","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 16","te":["silencio","presencia"]},{"i":"lao-tse-013","a":"lao-tse","t":"Lo parcial se vuelve completo; lo torcido, recto; lo vacío, lleno; lo gastado, nuevo.","o":"The partial becomes complete; the crooked, straight; the empty, full; the worn out, new.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 22","te":["cambio","esperanza"]},{"i":"lao-tse-014","a":"lao-tse","t":"No se exhibe, y por eso brilla.","o":"He is free from self-display, and therefore he shines","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 22","te":["autenticidad","autoestima"]},{"i":"lao-tse-015","a":"lao-tse","t":"Un viento violento no dura toda la mañana; un aguacero repentino no dura todo el día.","o":"A violent wind does not last for a whole morning; a sudden rain does not last for the whole day.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 23","te":["cambio","regulacion-emocional","naturaleza"]},{"i":"lao-tse-016","a":"lao-tse","t":"Quien se pone en puntas de pie no está firme; quien estira las piernas no camina con soltura.","o":"He who stands on his tiptoes does not stand firm; he who stretches his legs does not walk (easily).","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 23","te":["autenticidad","aceptacion"]},{"i":"lao-tse-017","a":"lao-tse","t":"La gravedad es la raíz de la ligereza; la quietud, la que gobierna el movimiento.","o":"Gravity is the root of lightness; stillness, the ruler of movement.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 26","te":["silencio","presencia"]},{"i":"lao-tse-018","a":"lao-tse","t":"El buen viajero no deja huellas de sus ruedas ni de sus pasos.","o":"The skilful traveller leaves no traces of his wheels or footsteps","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 27","te":["presencia","naturaleza"]},{"i":"lao-tse-019","a":"lao-tse","t":"Quien conoce a los demás es perspicaz; quien se conoce a sí mismo es sabio. Quien vence a otros es fuerte; quien se vence a sí mismo es poderoso.","o":"He who knows other men is discerning; he who knows himself is intelligent. He who overcomes others is strong; he who overcomes himself is mighty.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 33","te":["autoconocimiento","poder"]},{"i":"lao-tse-020","a":"lao-tse","t":"Quien está conforme con lo que tiene es rico.","o":"He who is satisfied with his lot is rich","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 33","te":["felicidad","deseo","aceptacion"]},{"i":"lao-tse-021","a":"lao-tse","t":"Lo blando vence a lo duro; lo débil, a lo fuerte.","o":"The soft overcomes the hard; and the weak the strong.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 36","te":["resiliencia","naturaleza"]},{"i":"lao-tse-022","a":"lao-tse","t":"El movimiento del Tao procede por contrarios.","o":"The movement of the Tao By contraries proceeds","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 40","te":["cambio","trascendencia"]},{"i":"lao-tse-023","a":"lao-tse","t":"Lo más blando del mundo choca contra lo más duro y lo vence.","o":"The softest thing in the world dashes against and overcomes the hardest","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 43","te":["resiliencia"]},{"i":"lao-tse-024","a":"lao-tse","t":"Quien está contento no teme la vergüenza. Quien sabe detenerse no incurre en culpa.","o":"Who is content Needs fear no shame. Who knows to stop Incurs no blame.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 44","te":["aceptacion","deseo"]},{"i":"lao-tse-025","a":"lao-tse","t":"No hay culpa mayor que consentir la ambición, ni calamidad mayor que no estar conforme con lo que uno tiene, ni falta mayor que el deseo de obtener.","o":"There is no guilt greater than to sanction ambition; no calamity greater than to be discontented with one's lot; no fault greater than the wish to be getting.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 46","te":["deseo","felicidad"]},{"i":"lao-tse-026","a":"lao-tse","t":"Por eso la suficiencia del contento es una suficiencia duradera e inmutable.","o":"Therefore the sufficiency of contentment is an enduring and unchanging sufficiency.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 46","te":["felicidad","aceptacion"]},{"i":"lao-tse-027","a":"lao-tse","t":"Cuanto más lejos va uno, fuera de sí, menos sabe.","o":"The farther that one goes out (from himself), the less he knows.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 47","te":["autoconocimiento","conocimiento"]},{"i":"lao-tse-028","a":"lao-tse","t":"Quien se dedica al estudio busca aumentar cada día su saber; quien se dedica al Tao busca disminuir cada día su hacer.","o":"He who devotes himself to learning (seeks) from day to day to increase (his knowledge); he who devotes himself to the Tao (seeks) from day to day to diminish (his doing).","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 48","te":["conocimiento","trascendencia"]},{"i":"lao-tse-029","a":"lao-tse","t":"Con quienes son buenos conmigo soy bueno; con quienes no lo son, también soy bueno: y así todos llegan a ser buenos.","o":"To those who are good (to me), I am good; and to those who are not good (to me), I am also good;--and thus (all) get to be good.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 49","te":["compasion","vinculos"]},{"i":"lao-tse-030","a":"lao-tse","t":"Quien conoce el Tao no se preocupa por hablar de él; quien siempre está dispuesto a hablar de él no lo conoce.","o":"He who knows (the Tao) does not (care to) speak (about it); he who is (ever ready to) speak about it does not know it.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 56","te":["silencio","conocimiento"]},{"i":"lao-tse-031","a":"lao-tse","t":"¡La desdicha! A su lado se encuentra la dicha. ¡La dicha! Debajo acecha la desdicha. ¿Quién sabe en qué terminará cada una?","o":"Misery!--happiness is to be found by its side! Happiness!--misery lurks beneath it! Who knows what either will come to in the end?","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 58","te":["felicidad","sufrimiento","incertidumbre"]},{"i":"lao-tse-032","a":"lao-tse","t":"No hay nada como la moderación.","o":"there is nothing like moderation","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 59","te":["habitos"]},{"i":"lao-tse-033","a":"lao-tse","t":"Gobernar un gran Estado es como cocinar pescados pequeños.","o":"Governing a great state is like cooking small fish.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 60","te":["poder","sociedad"]},{"i":"lao-tse-034","a":"lao-tse","t":"Y responder a la ofensa con bondad.","o":"and to recompense injury with kindness","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 63","te":["compasion","ira"]},{"i":"lao-tse-035","a":"lao-tse","t":"El árbol que llena los brazos nació de un brote diminuto; la torre de nueve pisos se levantó de un montón de tierra; el viaje de mil li empezó con un solo paso.","o":"The tree which fills the arms grew from the tiniest sprout; the tower of nine storeys rose from a (small) heap of earth; the journey of a thousand li commenced with a single step.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 64","te":["cambio","habitos","esperanza"]},{"i":"lao-tse-036","a":"lao-tse","t":"Hay que actuar antes de que algo aparezca; hay que poner orden antes de que empiece el desorden.","o":"Action should be taken before a thing has made its appearance; order should be secured before disorder has begun.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 64","te":["responsabilidad"]},{"i":"lao-tse-037","a":"lao-tse","t":"Los ríos y los mares reciben el tributo de todos los arroyos del valle porque saben estar más abajo que ellos.","o":"That whereby the rivers and seas are able to receive the homage and tribute of all the valley streams, is their skill in being lower than they","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 66","te":["poder","naturaleza"]},{"i":"lao-tse-038","a":"lao-tse","t":"Tengo tres tesoros que aprecio y conservo: el primero es la bondad; el segundo, la sobriedad; el tercero, no querer ponerme por delante de los demás.","o":"But I have three precious things which I prize and hold fast. The first is gentleness; the second is economy; and the third is shrinking from taking precedence of others.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 67","te":["compasion","autenticidad"]},{"i":"lao-tse-039","a":"lao-tse","t":"Con esa bondad puedo ser valiente.","o":"With that gentleness I can be bold","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 67","te":["compasion","miedo"]},{"i":"lao-tse-040","a":"lao-tse","t":"Saber y pensar que no sabemos es lo más alto; no saber y creer que sabemos es una enfermedad.","o":"To know and yet (think) we do not know is the highest (attainment); not to know (and yet think) we do know is a disease.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 71","te":["conocimiento","autoconocimiento"]},{"i":"lao-tse-041","a":"lao-tse","t":"Al nacer, el ser humano es flexible y débil; al morir, rígido y duro.","o":"Man at his birth is supple and weak; at his death, firm and strong.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 76","te":["muerte","cuerpo"]},{"i":"lao-tse-042","a":"lao-tse","t":"Así, la rigidez y la dureza acompañan a la muerte; la flexibilidad y la suavidad acompañan a la vida.","o":"Thus it is that firmness and strength are the concomitants of death; softness and weakness, the concomitants of life.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 76","te":["resiliencia","muerte"]},{"i":"lao-tse-043","a":"lao-tse","t":"No hay nada en el mundo más blando y débil que el agua, y sin embargo, para vencer lo firme y lo fuerte, nada la supera.","o":"There is nothing in the world more soft and weak than water, and yet for attacking things that are firm and strong there is nothing that can take precedence of it","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 78","te":["resiliencia","naturaleza"]},{"i":"lao-tse-044","a":"lao-tse","t":"Todos en el mundo saben que lo blando vence a lo duro y lo débil a lo fuerte, pero nadie es capaz de llevarlo a la práctica.","o":"Every one in the world knows that the soft overcomes the hard, and the weak the strong, but no one is able to carry it out in practice.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 78","te":["conocimiento","habitos"]},{"i":"lao-tse-045","a":"lao-tse","t":"Cuando dos partes se reconcilian después de una gran enemistad, siempre queda algún rencor.","o":"When a reconciliation is effected (between two parties) after a great animosity, there is sure to be a grudge remaining","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 79","te":["vinculos","ira"]},{"i":"lao-tse-046","a":"lao-tse","t":"Las palabras sinceras no son bellas; las palabras bellas no son sinceras.","o":"Sincere words are not fine; fine words are not sincere.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 81","te":["autenticidad","comunicacion"]},{"i":"lao-tse-047","a":"lao-tse","t":"Cuanto más da a los demás, más posee.","o":"The more that he expends for others, the more does he possess of his own","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 81","te":["compasion","vinculos"]},{"i":"lao-tse-048","a":"lao-tse","t":"Mis palabras son muy fáciles de entender y muy fáciles de practicar; pero nadie en el mundo es capaz de entenderlas y practicarlas.","o":"My words are very easy to know, and very easy to practise; but there is no one in the world who is able to know and able to practise them.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 70","te":["conocimiento","habitos"]},{"i":"lao-tse-049","a":"lao-tse","t":"La pureza y la quietud dan la norma justa a todo lo que existe bajo el cielo.","o":"Purity and stillness give the correct law to all under heaven.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 45","te":["silencio"]},{"i":"lao-tse-050","a":"lao-tse","t":"Quien presta atención indivisa a la respiración y la vuelve flexible al máximo puede ser como un niño pequeño.","o":"When one gives undivided attention to the (vital) breath, and brings it to the utmost degree of pliancy, he can become as a (tender) babe.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 10","te":["cuerpo","atencion","presencia"]},{"i":"lao-tse-051","a":"lao-tse","t":"Quien tiene en abundancia las virtudes del Tao es como un niño recién nacido.","o":"He who has in himself abundantly the attributes (of the Tao) is like an infant.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 55","te":["infancia","trascendencia"]},{"i":"lao-tse-052","a":"lao-tse","t":"El favor y la desgracia parecen igualmente temibles.","o":"Favour and disgrace would seem equally to be feared","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 13","te":["miedo","autoestima"]}],"ruta":"/recursos/voces-que-nos-habitan/","temasRuta":"/recursos/voces-que-nos-habitan/temas/","escuelas":[["fil","Filosofía"],["ini","Los comienzos"],["ori","Tradiciones orientales"],["pa","Psicoanálisis"]],"epocas":[["clasico","Clásicos"],["moderno","Modernos"]]};
